_getVisibilitySegmentForNonPublic() {
    const {visibility, tiers} = this;

    if (visibility === 'members') {
        return 'status:free,status:-free';
    }

    if (visibility === 'paid') {
        return 'status:-free';
    }

    if (visibility === 'tiers' && tiers) {
