const BLANK_LEXICAL = '{"root":{"children":[{"children":[],"direction":null,"format":"","indent":0,"type":"paragraph","version":1}],"direction":null,"format":"","indent":0,"type":"root","version":1}}';

// ember-cli-shims doesn't export these so we must get them manually
const {Comparable} = Ember;

function statusCompare(postA, postB) {
    let status1 = postA.get('status');
    let status2 = postB.get('status');

    // if any of those is empty
    if (!status1 && !status2) {
        return 0;
    }

    if (!status1 && status2) {
        return -1;
    }

    if (!status2 && status1) {
        return 1;
    }

    // We have to make sure, that scheduled posts will be listed first
    // after that, draft and published will be sorted alphabetically and don't need
    // any manual comparison.

    if (status1 === 'scheduled' && (status2 === 'draft' || status2 === 'published')) {
        return -1;
    }

    if (status2 === 'scheduled' && (status1 === 'draft' || status1 === 'published')) {
        return 1;
    }

    return compare(status1.valueOf(), status2.valueOf());
}

function publishedAtCompare(postA, postB) {
    let published1 = postA.get('publishedAtUTC');
    let published2 = postB.get('publishedAtUTC');

    if (!published1 && !published2) {
        return 0;
    }

    if (!published1 && published2) {
        return -1;
    }

    if (!published2 && published1) {
        return 1;
    }

    return compare(published1.valueOf(), published2.valueOf());
}

/**
 * Computes visibility segment string based on post visibility and tiers.
 * Handles 'public', 'members', 'paid', 'tiers', and unknown visibility types.
 */
function computeVisibilitySegment(post) {
    if (post.isPublic) {
        return post.settings.defaultContentVisibility === 'paid' ? 'status:-free' : 'status:free,status:-free';
    }

    const visibility = post.visibility;

    if (visibility === 'members') {
        return 'status:free,status:-free';
    }
    if (visibility === 'paid') {
        return 'status:-free';
    }
    if (visibility === 'tiers' && post.tiers) {
        return post.tiers.map(tier => `tier:${tier.slug}`).join(',');
    }

    return visibility;
}

