/**
 * Find the customer with the most recent subscription among multiple matched customers.
 *
 * @param {import('stripe').Stripe.Customer[]} customers
 * @returns {string|null} Customer ID, or undefined if none found
 */
_getMostRecentCustomerWithSubscription(customers) {
    let latestCustomer = customers[0];
    let latestSubscriptionTime = 0;

    for (const customer of customers) {
        if (!customer.subscriptions?.data?.length) {
            continue;
        }

        for (const subscription of customer.subscriptions.data) {
            if (
                subscription.current_period_end &&
                subscription.current_period_end > latestSubscriptionTime
            ) {
                latestSubscriptionTime = subscription.current_period_end;
                latestCustomer = customer;
            }
        }
    }

    return latestCustomer.id;
}

