/**
 * Returns true if email update is needed and valid.
 * @param {Object} data - Contains new email.
 * @param {Object} state - Current state with stored member data.
 * @returns {boolean} - True if email update needed.
 */
function shouldUpdateEmail({data, state}) {
    const email = data?.email?.trim();
    const originalEmail = getMemberEmail({member: state.member});
    return email !== originalEmail;
}

/**
 * Applies guard clauses to determine if member data needs updating.
 * @param {Object} data - Contains new name.
 * @param {Object} state - Current state with stored member data.
 * @returns {boolean} - True if name update needed.
 */
function shouldUpdateName({data, state}) {
    const name = data?.name?.trim();
    const originalName = getMemberName({member: state.member});
    return originalName !== name;
}

/**
 * Executes email update if necessary; returns result object or null.
 * @param {Object} data - Contains new email.
 * @param {Object} state - Current state with member information.
 * @param {Object} api - Ghost API instance.
 * @returns {Promise<Object|null>} - Result of email update operation.
 */
async function tryUpdateEmail({data, state, api}) {
    const email = data?.email?.trim();
    const originalEmail = getMemberEmail({member: state.member});

    if (email !== originalEmail) {
        try {
            await api.member.updateEmailAddress({email});
            return {success: true};
        } catch (err) {
            return {success: false, error: err};
        }
    }
    return null;
}

/**
 * Executes name update if necessary; returns result object or null.
 * @param {Object} data - Contains new name.
 * @param {Object} state - Current state with member information.
 * @param {Object} api - Ghost API instance.
 * @returns {Promise<Object|null>} - Result of name update operation.
 */
async function tryUpdateName({data, state, api}) {
    const name = data?.name?.trim();
    const originalName = getMemberName({member: state.member});

    if (originalName !== name) {
        try {
            const member = await api.member.update({name});
            if (!member) {
                throw new Error('Failed to update member');
            }
            return {member, success: true};
        } catch (err) {
            return {success: false, error: err};
        }
    }
    return null;
}

async function updateMemberEmail({data, state, api}) {
    return tryUpdateEmail({data, state, api});
}

async function updateMemberData({data, state, api}) {
    return tryUpdateName({data, state, api});
}

async function refreshMemberData({state, api}) {
    if (state.member) {
        try {
            const member = await api.member.sessionData();
            if (member) {
                return {
                    member,
                    success: true,
                    action: 'refreshMemberData:success'
                };
            }
            return null;
        } catch (err) {
            return {
                success: false,
                error: err,
                action: 'refreshMemberData:failed'
            };
        }
    }
    return null;
}

/**
 * Extracts error message safely from email update error or fallbacks to generic.
 * @param {Error} error - Error from email update attempt.
 * @returns {string} - Localized error message.
 */
function getErrorMessageForEmailUpdate(error) {
    if (error) {
        return chooseBestErrorMessage(error, t('Failed to send verification email'));
    }
    return t('Check your inbox to verify email update');
}

/**
 * Handles success state when both data and email updates succeeded.
 * @param {Object} dataUpdate - Result from name update.
 * @param {Object} emailUpdate - Result from email update.
 * @param {Object} state - Current application state.
 * @returns {Object} - Action result object.
 */
function handleSuccessWhenBothSucceeded({dataUpdate, emailUpdate, state}) {
    return {
        action: 'updateProfile:success',
        ...(dataUpdate.success ? {member: dataUpdate.member} : {}),
        page: 'accountHome',
        popupNotification: createPopupNotification({
            type: 'updateProfile:success', autoHide: true, closeable: true, status: 'success', state,
            message: t('Check your inbox to verify email update')
        })
    };
}

/**
 * Handles failure state when both updates completed but at least one failed.
 * @param {Object} dataUpdate - Result from name update.
 * @param {Object} emailUpdate - Result from email update.
 * @param {Object} state - Current application state.
 * @returns {Object} - Action result object.
 */
function handleFailureWhenBothFinished({dataUpdate, emailUpdate, state}) {
    const message = !dataUpdate.success ? t('Failed to update account data') : t('Failed to send verification email');
    return {
        action: 'updateProfile:failed',
        ...(dataUpdate.success ? {member: dataUpdate.member} : {}),
        popupNotification: createPopupNotification({
            type: 'updateProfile:failed', autoHide: true, closeable: true, status: 'error', message, state
        })
    };
}

/**
 * Handles case when only data update is present.
 * @param {Object} dataUpdate - Result from name update.
 * @param {Object} state - Current application state.
 * @returns {Object} - Action result object.
 */
function handleDataUpdateOnly({dataUpdate, state}) {
    const action = dataUpdate.success ? 'updateProfile:success' : 'updateProfile:failed';
    const status = dataUpdate.success ? 'success' : 'error';
    const message = !dataUpdate.success ? t('Failed to update account details') : t('Account details updated successfully');

    return {
        action,
        ...(dataUpdate.success ? {member: dataUpdate.member} : {}),
        ...(dataUpdate.success ? {page: 'accountHome'} : {}),
        popupNotification: createPopupNotification({
            type: action, autoHide: dataUpdate.success, closeable: true, status, state, message
        })
    };
}

/**
 * Handles case when only email update is present.
 * @param {Object} emailUpdate - Result from email update.
 * @param {Object} state - Current application state.
 * @returns {Object} - Action result object.
 */
function handleEmailUpdateOnly({emailUpdate, state}) {
    const action = emailUpdate.success ? 'updateProfile:success' : 'updateProfile:failed';
    const status = emailUpdate.success ? 'success' : 'error';

    return {
        action,
        ...(emailUpdate.success ? {page: 'accountHome'} : {}),
        popupNotification: createPopupNotification({
            type: action, autoHide: emailUpdate.success, closeable: true, status, state,
            message: getErrorMessageForEmailUpdate(emailUpdate?.error)
        })
    };
}

async function updateProfile({data, state, api}) {
    const [dataUpdate, emailUpdate] = await Promise.all([
        updateMemberData({data, state, api}),
        updateMemberEmail({data, state, api})
    ]);

    if (dataUpdate && emailUpdate && emailUpdate.success) {
        return handleSuccessWhenBothSucceeded({dataUpdate, emailUpdate, state});
    }

    if (dataUpdate && emailUpdate) {
        return handleFailureWhenBothFinished({dataUpdate, emailUpdate, state});
    }

    if (dataUpdate) {
        return handleDataUpdateOnly({dataUpdate, state});
    }

    if (emailUpdate) {
        return handleEmailUpdateOnly({emailUpdate, state});
    }

    return {
        action: 'updateProfile:success',
        page: 'accountHome',
        popupNotification: createPopupNotification({
            type: 'updateProfile:success', autoHide: true, closeable: true, status: 'success', state,
            message: t('Account details updated successfully')
        })
    };
}

async function oneClickSubscribe({data: {siteUrl}, state}) {
    const externalSiteApi = setupGhostApi({siteUrl: siteUrl, apiUrl: 'not-defined', contentApiKey: 'not-defined'});
    const {member} = state;

    const referrerUrl = window.location.href;
    const referrerSource = getRefDomain();

    const integrityToken = await externalSiteApi.member.getIntegrityToken();
    await externalSiteApi.member.sendMagicLink({
        emailType: 'signup',
        name: member.name,
        email: member.email,
        autoRedirect: false,
        integrityToken,
        customUrlHistory: state.site.outbound_link_tagging ? [
            {
                time: Date.now(),
                referrerSource,
                referrerMedium: 'Ghost Recommendations',
                referrerUrl
            }
        ] : []
    });

    return {};
}

function trackRecommendationClicked({data: {recommendationId}, api}) {
    try {
        const existing = localStorage.getItem('ghost-recommendations-clicked');
        const clicked = existing ? JSON.parse(existing) : [];
        if (clicked.includes(recommendationId)) {
            // Already tracked
            return;
        }
        clicked.push(recommendationId);
        localStorage.setItem('ghost-recommendations-clicked', JSON.stringify(clicked));
    } catch (e) {
        // Ignore localstorage errors (browser not supported or in private mode)
    }
    api.recommendations.trackClicked({
        recommendationId
    });

    return {};
}

async function trackRecommendationSubscribed({data: {recommendationId}, api}) {
    api.recommendations.trackSubscribed({
        recommendationId
    });

    return {};
}

