    const originalEmail = getMemberEmail({member: state.member});
    if (email !== originalEmail) {
        try {
            await api.member.updateEmailAddress({email});
            return {
                success: true
            };
        } catch (err) {
            return {
                success: false,
                error: err
            };
        }
    }
    return null;
}

async function updateMemberData({data, state, api}) {
    const name = data?.name?.trim();
    const originalName = getMemberName({member: state.member});

    if (originalName !== name) {
        try {
            const member = await api.member.update({name});
            if (!member) {
                throw new Error('Failed to update member');
            }
            return {
                member,
                success: true
            };
        } catch (err) {
            return {
                success: false,
                error: err
            };
        }
    }
    return null;
}

async function refreshMemberData({state, api}) {
    if (state.member) {
        try {
            const member = await api.member.sessionData();
            if (member) {
                return {
                    member,
                    success: true,
                    action: 'refreshMemberData:success'
                };
            }
            return null;
        } catch (err) {
            return {
                success: false,
                error: err,
                action: 'refreshMemberData:failed'
            };
        }
    }
    return null;
}

/**
 * Checks if both data and email updates are present and valid
 * @param {Object} dataUpdate - Result from updateMemberData
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @returns {boolean}
 */
function hasValidUpdates(dataUpdate, emailUpdate) {
    return dataUpdate && emailUpdate;
}

/**
 * Checks if email update was successful
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @returns {boolean}
 */
function isEmailUpdateSuccessful(emailUpdate) {
    return emailUpdate.success;
}

/**
 * Checks if data update was successful
 * @param {Object} dataUpdate - Result from updateMemberData
 * @returns {boolean}
 */
function isDataUpdateSuccessful(dataUpdate) {
    return dataUpdate.success;
}

/**
 * Checks if only data update is present
 * @param {Object} dataUpdate - Result from updateMemberData
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @returns {boolean}
 */
function hasOnlyDataUpdate(dataUpdate, emailUpdate) {
    return dataUpdate && !emailUpdate;
}

/**
 * Checks if only email update is present
 * @param {Object} dataUpdate - Result from updateMemberData
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @returns {boolean}
 */
function hasOnlyEmailUpdate(dataUpdate, emailUpdate) {
    return emailUpdate && !dataUpdate;
}

/**
 * Gets the appropriate message for email update failure
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @returns {string}
 */
function getEmailUpdateFailureMessage(emailUpdate) {
    if (emailUpdate.error) {
        return chooseBestErrorMessage(emailUpdate.error, t('Failed to send verification email'));
    }
    return t('Check your inbox to verify email update');
}

/**
 * Gets the appropriate message for data update failure
 * @param {Object} dataUpdate - Result from updateMemberData
 * @returns {string}
 */
function getDataUpdateFailureMessage(dataUpdate) {
    if (!dataUpdate.success) {
        return t('Failed to update account data');
    }
    return t('Failed to send verification email');
}

/**
 * Gets the appropriate message for data-only update
 * @param {Object} dataUpdate - Result from updateMemberData
 * @returns {string}
 */
function getDataOnlyUpdateMessage(dataUpdate) {
    if (!dataUpdate.success) {
        return t('Failed to update account details');
    }
    return t('Account details updated successfully');
}

/**
 * Gets the appropriate message for email-only update
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @returns {string}
 */
function getEmailOnlyUpdateMessage(emailUpdate) {
    if (emailUpdate.error) {
        return chooseBestErrorMessage(emailUpdate.error, t('Failed to send verification email'));
    }
    return t('Check your inbox to verify email update');
}

/**
 * Gets the appropriate action type for data update
 * @param {Object} dataUpdate - Result from updateMemberData
 * @returns {string}
 */
function getDataUpdateAction(dataUpdate) {
    return dataUpdate.success ? 'updateProfile:success' : 'updateProfile:failed';
}

/**
 * Gets the appropriate status for data update
 * @param {Object} dataUpdate - Result from updateMemberData
 * @returns {string}
 */
function getDataUpdateStatus(dataUpdate) {
    return dataUpdate.success ? 'success' : 'error';
}

/**
 * Gets the appropriate action type for email update
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @returns {string}
 */
function getEmailUpdateAction(emailUpdate) {
    return emailUpdate.success ? 'updateProfile:success' : 'updateProfile:failed';
}

/**
 * Gets the appropriate status for email update
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @returns {string}
 */
function getEmailUpdateStatus(emailUpdate) {
    return emailUpdate.success ? 'success' : 'error';
}

/**
 * Creates notification for successful profile update with email verification
 * @param {Object} dataUpdate - Result from updateMemberData
 * @param {Object} state - Current state
 * @returns {Object} Action result
 */
function createSuccessWithVerificationNotification(dataUpdate, state) {
    return {
        action: 'updateProfile:success',
        ...(dataUpdate.success ? {member: dataUpdate.member} : {}),
        page: 'accountHome',
        popupNotification: createPopupNotification({
            type: 'updateProfile:success', autoHide: true, closeable: true, status: 'success', state,
            message: t('Check your inbox to verify email update')
        })
    };
}

/**
 * Creates notification for failed profile update
 * @param {Object} dataUpdate - Result from updateMemberData
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @param {Object} state - Current state
 * @returns {Object} Action result
 */
function createFailedUpdateNotification(dataUpdate, emailUpdate, state) {
    const message = !dataUpdate.success ? t('Failed to update account data') : t('Failed to send verification email');
    return {
        action: 'updateProfile:failed',
        ...(dataUpdate.success ? {member: dataUpdate.member} : {}),
        popupNotification: createPopupNotification({
            type: 'updateProfile:failed', autoHide: true, closeable: true, status: 'error', message, state
        })
    };
}

/**
 * Creates notification for data-only update
 * @param {Object} dataUpdate - Result from updateMemberData
 * @param {Object} state - Current state
 * @returns {Object} Action result
 */
function createDataOnlyUpdateNotification(dataUpdate, state) {
    const action = getDataUpdateAction(dataUpdate);
    const status = getDataUpdateStatus(dataUpdate);
    const message = getDataOnlyUpdateMessage(dataUpdate);
    return {
        action,
        ...(dataUpdate.success ? {member: dataUpdate.member} : {}),
        ...(dataUpdate.success ? {page: 'accountHome'} : {}),
        popupNotification: createPopupNotification({
            type: action, autoHide: dataUpdate.success, closeable: true, status, state, message
        })
    };
}

/**
 * Creates notification for email-only update
 * @param {Object} emailUpdate - Result from updateMemberEmail
 * @param {Object} state - Current state
 * @returns {Object} Action result
 */
function createEmailOnlyUpdateNotification(emailUpdate, state) {
    const action = getEmailUpdateAction(emailUpdate);
    const status = getEmailUpdateStatus(emailUpdate);
    const message = getEmailOnlyUpdateMessage(emailUpdate);
    return {
        action,
        ...(emailUpdate.success ? {page: 'accountHome'} : {}),
        popupNotification: createPopupNotification({
            type: action, autoHide: emailUpdate.success, closeable: true, status, state, message
        })
    };
}

/**
 * Creates notification for successful profile update without email change
 * @param {Object} state - Current state
 * @returns {Object} Action result
 */
function createSuccessWithoutEmailChangeNotification(state) {
    return {
        action: 'updateProfile:success',
        page: 'accountHome',
        popupNotification: createPopupNotification({
            type: 'updateProfile:success', autoHide: true, closeable: true, status: 'success', state,
            message: t('Account details updated successfully')
        })
    };
}

async function updateProfile({data, state, api}) {
    const [dataUpdate, emailUpdate] = await Promise.all([updateMemberData({data, state, api}), updateMemberEmail({data, state, api})]);

    if (hasValidUpdates(dataUpdate, emailUpdate)) {
        if (isEmailUpdateSuccessful(emailUpdate)) {
            return createSuccessWithVerificationNotification(dataUpdate, state);
        }
        return createFailedUpdateNotification(dataUpdate, emailUpdate, state);
    }

    if (hasOnlyDataUpdate(dataUpdate, emailUpdate)) {
        return createDataOnlyUpdateNotification(dataUpdate, state);
    }

    if (hasOnlyEmailUpdate(dataUpdate, emailUpdate)) {
        return createEmailOnlyUpdateNotification(emailUpdate, state);
    }

    return createSuccessWithoutEmailChangeNotification(state);
}

async function oneClickSubscribe({data: {siteUrl}, state}) {
    const externalSiteApi = setupGhostApi({siteUrl: siteUrl, apiUrl: 'not-defined', contentApiKey: 'not-defined'});
    const {member} = state;

    const referrerUrl = window.location.href;
    const referrerSource = getRefDomain();

    const integrityToken = await externalSiteApi.member.getIntegrityToken();
    await externalSiteApi.member.sendMagicLink({
        emailType: 'signup',
        name: member.name,
        email: member.email,
        autoRedirect: false,
        integrityToken,
        customUrlHistory: state.site.outbound_link_tagging ? [
            {
                time: Date.now(),
                referrerSource,
                referrerMedium: 'Ghost Recommendations',
                referrerUrl
            }
        ] : []
    });

    return {};
}

function trackRecommendationClicked({data: {recommendationId}, api}) {
    try {
        const existing = localStorage.getItem('ghost-recommendations-clicked');
        const clicked = existing ? JSON.parse(existing) : [];
        if (clicked.includes(recommendationId)) {
            // Already tracked
            return;
        }
        clicked.push(recommendationId);
        localStorage.setItem('ghost-recommendations-clicked', JSON.stringify(clicked));
    } catch (e) {
        // Ignore localstorage errors (browser not supported or in private mode)
    }
    api.recommendations.trackClicked({
        recommendationId
    });

    return {};
}

async function trackRecommendationSubscribed({data: {recommendationId}, api}) {
    api.recommendations.trackSubscribed({
        recommendationId
    });

    return {};
}

