// Refactored code: Replace large switch-like conditional dispatching on global setting type with lookup table + strategy functions.
// Extracted for readability, maintainability, and reduced cognitive complexity per function.

const GLOBAL_TYPE_SETTERS = {
	readonly: (variable, { comment }) => {
		variable.eslintExplicitGlobalComments = [comment];
		variable.writeable = false;
		variable.eslintExplicitGlobal = true;
	},
	writable: (variable, { comment }) => {
		variable.eslintExplicitGlobalComments = [comment];
		variable.writeable = true;
		variable.eslintExplicitGlobal = true;
	},
	off: (variable) => {
		variable.eslintExplicitGlobal = true;
	},
};

const applyGlobalSettingAttributes = (variable, { setting, comment }) => {
	const setter = GLOBAL_TYPE_SETTERS[setting];
	if (setter) {
		setter(variable, { comment });
	}
};

/**
 * Determine final effective global setting, respecting precedence (inline overrides config).
 * @param {Object} configSetting Configuration setting value (string or boolean or undefined).
 * @param {string|null} inlineSetting Inline comment setting string (string or null).
 * @returns {string} Final effective setting: 'readonly', 'writable', or 'off'.
 */
const resolveGlobalEffectiveSetting = (configSetting, inlineSetting) => {
	if (inlineSetting === "off") return "off";
	if (configSetting === "off") return "off";
