					if (shouldSkipVariable(variable, scope)) {
						continue;
					}

					const def = variable.defs?.[0];

					if (def) {
						handleVariableDefinition(variable, def, scope);
					}

					if (shouldReportUnusedVariable(variable)) {
						unusedVars.push(variable);
					}
