		function fixVariableDeclarator(parent, id) {
			const grandParent = parent.parent;

			if (grandParent.declarations.length === 1) {
				return fixer.removeRange(grandParent.range);
			}

			if (tokenBefore?.value === ",") {
				return fixer.removeRange([
					tokenBefore.range[0],
					parent.range[1],
				]);
			}

			return fixer.removeRange([
				parent.range[0],
				tokenAfter.range[1],
			]);
		}

