			if (tokenBefore?.value === "{") {
				return fixer.removeRange([
					parent.range[0],
					tokenAfter.range[1],
				]);
			}

			return fixer.removeRange([
				getPreviousTokenStart(parent),
				parent.range[1],
			]);
		}

		/**
		 * Fix import namespace specifier
