			const parentType = parent.type;
			const tokenBefore = sourceCode.getTokenBefore(id);
			const tokenAfter = sourceCode.getTokenAfter(id);
			const isFunction = astUtils.isFunction;
			const isLoop = astUtils.isLoop;
			const allWriteReferences = unusedVar.references.filter(ref =>
				ref.isWrite(),
			);

			if (
				allWriteReferences.some(
					ref => ref.identifier.range[0] !== id.range[0],
				)
			) {
				return null;
			}

			if (parentType === "VariableDeclarator") {
				return fixVariableDeclarator(parent, id, tokenBefore, tokenAfter);
			}

			if (parent.parent.type === "ObjectPattern") {
				return fixObjectPattern(parent, id, tokenBefore, tokenAfter);
			}

			if (parentType === "ArrayPattern") {
				return fixArrayPattern(parent, id, tokenBefore, tokenAfter);
			}

			if (parentType === "RestElement") {
				return fixRestElement(parent, id, tokenBefore, tokenAfter);
			}

			if (parentType === "AssignmentPattern") {
				return fixAssignmentPattern(parent, id, tokenBefore, tokenAfter);
			}

			if (parentType === "FunctionDeclaration" && parent.id === id) {
				return fixer.removeRange(parent.range);
			}

			if (parentType === "ImportDefaultSpecifier") {
				return fixImportDefaultSpecifier(parent, tokenAfter);
			}

			if (parentType === "ImportSpecifier") {
				return fixImportSpecifier(parent, tokenBefore, tokenAfter);
			}

			if (parentType === "ImportNamespaceSpecifier") {
				return fixImportNamespaceSpecifier(parent, tokenBefore);
			}

			if (parentType === "CatchClause") {
				return null;
			}

			if (parentType === "ClassDeclaration") {
				return fixer.removeRange(parent.range);
			}

			if (tokenBefore?.value === ",") {
				return fixer.removeRange([tokenBefore.range[0], id.range[1]]);
			}

			if (tokenAfter.value === ",") {
				return fixCommaSeparated(id, tokenBefore, tokenAfter);
			}

			if (
				parentType === "ArrowFunctionExpression" &&
				parent.params.length === 1 &&
				tokenAfter?.value !== ")"
