		return false;
	}

	const scope = this.getScope(node);
	if (!scope) {
		return false;
	}

	const variable = scope.set.get(node.name);
	if (!variable) {
		return false;
	}

	if (variable.identifiers.length === 0) {
		return true;
	}

	if (
		variable.identifiers.length === 1 &&
		variable.identifiers[0] !== node
	) {
		return true;
	}

	return variable.identifiers.every(identifier => {
		const isWrite = variable.references.some(
			ref => ref.identifier === identifier && ref.isWrite(),
		);

		return !isWrite;
	});
};

SourceCode.prototype.traverse = function () {
	if (this._traverseCache) {
		return this._traverseCache;
	}

	return (this._traverseCache = traverse(this.ast, {
		visitorKeys: this.visitorKeys || defaultVisitorKeys,
	}));
};

SourceCode.prototype.applyLanguageOptions = function (
	languageOptions,
) {
	const {
		globals: configGlobals = {},
		ecmaVersion = 5,
		sourceType = "script",
	} = languageOptions;
	const esGlobals = globals.es2015;

	// Set up scope manager if needed
	if (!this.scopeManager) {
		this.scopeManager = eslintScope.analyze(this.ast, {
			ignoreEval: true,
			ecmaVersion,
			sourceType,
			...this.visitorKeys,
		});
	}

	const globalScope = this.scopeManager.scopes[0];

	// Add predefined ES globals
	Object.keys(esGlobals).forEach(name => {
		if (configGlobals[name] !== "off") {
			const variable = new eslintScope.Variable(
				name,
				globalScope,
				{
					name,
					eslintImplicitGlobalSetting:
						esGlobals[name] === "writable" ? "writable" : "readonly",
					eslintExplicitGlobal: false,
					eslintExplicitGlobalComments: void 0,
					writeable: esGlobals[name],
					defs: [],
				},
			);

			globalScope.set.set(name, variable);
		}
	});

	// Process custom globals from config and inline comments
	const inlineComments = this.getInlineConfigNodes();
	const { globals: inlineGlobals } = astUtils.getInlineConfig(
		inlineComments,
		this.text,
	);

	const mergedGlobals = {
		...configGlobals,
		...inlineGlobals,
	};

	Object.keys(mergedGlobals).forEach(name => {
		if (name in esGlobals) {
			return;
		}

		const setting = mergedGlobals[name];
		if (setting === "off") {
			return;
		}

		// Skip if already added explicitly
		if (globalScope.set.has(name)) {
			return;
		}

		const variable = new eslintScope.Variable(
			name,
			globalScope,
			{
				name,
				eslintImplicitGlobalSetting: void 0,
				eslintExplicitGlobal: name in inlineGlobals,
				eslintExplicitGlobalComments: [],
				writeable: setting === true || setting === "writable",
				defs: [],
			},
		);

		globalScope.set.set(name, variable);

		if (name in inlineGlobals) {
			variable.eslintExplicitGlobalComments.push(
				...inlineComments.filter(comment =>
					comment.value.includes(`globals ${name}`),
				),
			);
		}
	});

	// Tag variables declared in code but also declared in inline globals
	Object.keys(inlineGlobals).forEach(name => {
		const existing = globalScope.set.get(name);
		if (existing && existing.defs.length === 0) {
			existing.eslintExplicitGlobal = true;
			existing.eslintExplicitGlobalComments = [];
		}
	});

	// Ensure variables from inline comments without `writeable` or `readonly` get default attribute
	Object.keys(inlineGlobals).forEach(name => {
		const setting = inlineGlobals[name];
		if (setting === true || setting === "writable") {
			return;
		}
		const variable = globalScope.set.get(name);
		if (variable && setting !== "off" && typeof setting !== "undefined") {
			variable.writeable = setting === "writeable";
		}
	});
};

SourceCode.prototype.finalize = function () {
	const globalScope = this.scopeManager.scopes[0];

	// Ensure all implicit global variables have correct attributes
	globalScope.implicit.set.forEach(variable => {
		if (!variable.eslintImplicitGlobalSetting) {
			variable.eslintImplicitGlobalSetting = "writable";
		}
		variable.writeable = true;
	});

	// Resolve unresolved references
	globalScope.through.forEach(ref => {
		for (let scope = globalScope; scope; scope = scope.upper) {
			const variable = scope.set.get(ref.identifier.name);
			if (variable) {
				ref.resolved = variable;
				break;
			}
		}
	});

	// Ensure global variables declared in code are properly handled
	globalScope.variables.forEach(variable => {
		if (variable.defs.length > 0) {
			const [def] = variable.defs;
			if (def.type === "Variable" || def.type === "FunctionName") {
				if (variable.eslintImplicitGlobalSetting) {
					variable.eslintImplicitGlobalSetting = variable.writeable
						? "writable"
						: "readonly";
				}
			}
		}
	});
};

SourceCode.prototype.applyInlineConfig = function () {
	const comments = this.getInlineConfigNodes();
	const config = astUtils.getInlineConfig(comments, this.text);

	if (!config || config.configs.length === 0) {
		return {
			configs: [],
			problems: [],
		};
	}

	return {
		configs: config.configs.map(c => ({
			config: c,
			comments: [],
		})),
		problems: config.problems,
	};
};

