						value: /(?:)/u, // eslint-disable-line regexp/no-empty-group -- Test data for regex comparison
						regex: { pattern: "(?:)", flags: "u" },
					},
					expected: true,
				},
				{
					nodeA: {
						type: "Literal",
						value: null,
						regex: { pattern: "(?:)", flags: "u" },
					},
					nodeB: {
						type: "Literal",
						value: null,
						regex: { pattern: "(?:)", flags: "u" },
