	describe("isInLoop", () => {
		/**
		 * Asserts that the unique node of the given type in the code is either
		 * in a loop or not in a loop.
		 * @param {string} code the code to check.
		 * @param {string} nodeType the type of the node to consider. The code
		 *      must have exactly one node of this type.
		 * @param {boolean} expectedInLoop the expected result for whether the
		 *      node is in a loop.
		 * @returns {void}
		 */
		function assertNodeTypeInLoop(code, nodeType, expectedInLoop) {
			const results = [];

			prepareValidation(testConfig => {
				linter.verify(code, testConfig);
				return results;
			}, nodeType, results);

			assert.lengthOf(results, 1);
			assert.strictEqual(results[0], expectedInLoop);
		}

		/**
		 * Creates a linter configuration for isInLoop testing.
		 * @param {string} nodeType The type of node to test.
		 * @param {Array} results Array to collect results.
		 * @returns {Object} Linter configuration object.
		 */
		function createValidationConfig(nodeType, results) {
			return {
				plugins: {
					test: {
						rules: {
							checker: {
								create: mustCall(() => ({
									[nodeType]: mustCall(node => {
										results.push(astUtils.isInLoop(node));
									}),
								})),
							},
						},
					},
				},
				rules: { "test/checker": "error" },
			};
		}

		/**
		 * Prepares and executes validation with provided configuration.
		 * @param {Function} configFactory Function that creates test config.
		 * @param {string} nodeType The type of node to test.
		 * @param {Array} results Array to collect results.
		 * @returns {void}
		 */
		function prepareValidation(configFactory, nodeType, results) {
			linter.verify(code, configFactory(nodeType, results));
		}

		it("should return true for a loop itself", () => {
			assertNodeTypeInLoop("while (a) {}", "WhileStatement", true);
		});

		it("should return true for a loop condition", () => {
			assertNodeTypeInLoop("while (a) {}", "Identifier", true);
		});

		it("should return true for a loop assignee", () => {
			assertNodeTypeInLoop(
				"for (var a in b) {}",
				"VariableDeclaration",
				true,
			);
		});

		it("should return true for a node within a loop body", () => {
			assertNodeTypeInLoop(
				"for (var a of b) { console.log('Hello'); }",
				"Literal",
				true,
			);
		});

		it("should return false for a node outside a loop body", () => {
			assertNodeTypeInLoop(
				"while (true) {} a(b);",
				"CallExpression",
				false,
			);
		});

		it("should return false when the loop is not in the current function", () => {
			assertNodeTypeInLoop(
