"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const assert = require("chai").assert,
	espree = require("espree"),
	TokenStore = require("../../../../../lib/languages/js/source-code/token-store");

//------------------------------------------------------------------------------
// Constants
//------------------------------------------------------------------------------

const DEFAULT_CONFIG = {
	loc: true,
	range: true,
	tokens: true,
	comment: true,
};

const SOURCE_CODE =
		"/*A*/var answer/*B*/=/*C*/a/*D*/* b/*E*///F\n    call();\n/*Z*/",
	AST = espree.parse(SOURCE_CODE, DEFAULT_CONFIG),
	TOKENS = AST.tokens,
	COMMENTS = AST.comments,
	Program = AST,
	VariableDeclaration = Program.body[0],
	VariableDeclarator = VariableDeclaration.declarations[0],
	BinaryExpression = VariableDeclarator.init,
	CallExpression = Program.body[1].expression;

//------------------------------------------------------------------------------
// Helpers
//------------------------------------------------------------------------------

/**
 * Checks the values of tokens against an array of expected values.
 * @param {Token[]} tokens Tokens returned from the API.
 * @param {string[]} expected Expected token values
 * @returns {void}
 */
function check(tokens, expected) {
	const length = tokens.length;

	assert.strictEqual(length, expected.length);
	for (let i = 0; i < length; i++) {
		assert.strictEqual(tokens[i].value, expected[i]);
	}
}

/**
 * Ensures numeric count is non-negative.
 * @param {number} count The count to validate.
 * @returns {number} Validated count.
 */
function assertNonNegativeCount(count) {
	if (count < 0) {
		throw new RangeError("count must be a non-negative number");
	}
	return count;
}

/**
 * Extracts options from arguments, handling both single-object and legacy forms.
 * @param {number|Object} [arg1] The first argument (either count or options).
 * @param {number} [arg2] The second argument (either filter or padding).
 * @returns {Object} Normalized options.
 */
function normalizeGetTokensOptions(arg1, arg2) {
	if (typeof arg1 === "number") {
		const count = assertNonNegativeCount(arg1);
		return {
			countBefore: count,
			countAfter: typeof arg2 === "number" ? assertNonNegativeCount(arg2) : 0,
			filter: typeof arg2 === "function" ? arg2 : null,
		};
	}

	if (arg1 && typeof arg1 === "object" && !Array.isArray(arg1)) {
		return {
			countBefore: typeof arg1.count === "number" ? assertNonNegativeCount(arg1.count) : 0,
			countAfter: 0,
			filter: arg1.filter || null,
			includeComments: arg1.includeComments || false,
		};
	}

	return {
		countBefore: 0,
		countAfter: 0,
		filter: null,
		includeComments: false,
	};
}

