	stats = false,
	warnIgnored = true,
	passOnNoPatterns = false,
	ruleFilter = () => true,
	...unknownOptions
}) {
	const errors = [];

	const unknownOptionKeys = Object.keys(unknownOptions);
	errors.push(...validateUnknownOptions(unknownOptionKeys));

	// Boolean options
	errors.push(
		...validateBooleanOption("allowInlineConfig", allowInlineConfig),
	);
	errors.push(...validateBooleanOption("cache", cache));
	errors.push(
		...validateBooleanOption("errorOnUnmatchedPattern", errorOnUnmatchedPattern),
	);
	errors.push(...validateBooleanOption("globInputPaths", globInputPaths));
	errors.push(...validateBooleanOption("ignore", ignore));
	errors.push(...validateBooleanOption("stats", stats));
	errors.push(...validateBooleanOption("warnIgnored", warnIgnored));
	errors.push(
		...validateBooleanOption("passOnNoPatterns", passOnNoPatterns),
	);

	// String options
	errors.push(
		...validateNonEmptyStringOption(
			"cacheLocation",
			cacheLocation,
		),
	);
	errors.push(
		...validateNonEmptyStringOption("cwd", cwd) &&
			!path.isAbsolute(cwd)
			? ["'cwd' must be an absolute path."]
			: [],
	);

	// Object or null options
	errors.push(
		...validateObjectOrNullOption("baseConfig", baseConfig),
	);
	errors.push(
		...validateObjectOrNullOption("overrideConfig", overrideConfig),
	);

	// String or true or null options
	errors.push(
		...validateStringOrTrueOrNullOption("overrideConfigFile", overrideConfigFile),
	);

	// Cache strategy
	if (cacheStrategy !== "metadata" && cacheStrategy !== "content") {
		errors.push(
			'\'cacheStrategy\' must be any of "metadata", "content".',
		);
	}

	// Concurrency
	errors.push(...validateConcurrency(concurrency));

	// Fix and fixTypes
	if (typeof fix !== "boolean" && typeof fix !== "function") {
		errors.push("'fix' must be a boolean or a function.");
	}
	if (fixTypes !== null && !isFixTypeArray(fixTypes)) {
		errors.push(
			'\'fixTypes\' must be an array of any of "directive", "problem", "suggestion", and "layout".',
		);
	}

