	const validateFlags = validateArrayOption(
		"flags",
		isEmptyArrayOrArrayOfNonEmptyString,
		"'flags' must be an array of non-empty strings.",
	);
	errors.push(...validateFlags(flags));

	// Ignore patterns
	if (
		!isEmptyArrayOrArrayOfNonEmptyString(ignorePatterns) &&
		ignorePatterns !== null
	) {
		errors.push(
			"'ignorePatterns' must be an array of non-empty strings or null.",
		);
	}

