				ruleId: "foo-rule",
				message: "hello world",
				line: 1,
				column: 1,
			});
		});

		it("should infer an 'endLine' and 'endColumn' property when using the object-based context.report API", () => {
			fileReport.addRuleMessage("foo-rule", 2, {
				node,
				message: "hello world",
			});

			assert.deepStrictEqual(fileReport.messages[0], {
				severity: 2,
				ruleId: "foo-rule",
				message: "hello world",
				line: 1,
				column: 1,
				endLine: 1,
				endColumn: 4,
