			fileReport.addRuleMessage("foo-rule", 2, {
				loc: { line: 1, column: 1 },
				message: "hello world",
			});
			assert.deepStrictEqual(fileReport.messages[0], {
				severity: 2,
				ruleId: "foo-rule",
				message: "hello world",
				line: 1,
				column: 2,
			});
