				fix,
			);
			assert.notStrictEqual(
				fileReport.messages[0].suggestions[0].fix.range,
				fix.range,
			);
			assert.notStrictEqual(
				fileReport.messages[0].suggestions[0].fix,
				additionalFix,
			);
			assert.notStrictEqual(
