					yield fix;
					yield additionalFix;
				},
			});

			assertFixMatches(true);
			assertAdditionalFixNoMatch();
		});

		it("should deep clone returned suggestion fix object", () => {
			fileReport.addRuleMessage("foo-rule", 2, {
