"use strict";

//-----------------------------------------------------------------------------
// Requirements
//-----------------------------------------------------------------------------

const childProcess = require("node:child_process");
const fs = require("node:fs");
const assert = require("chai").assert;
const path = require("node:path");
const os = require("node:os");

//------------------------------------------------------------------------------
// Data
//------------------------------------------------------------------------------

const EXECUTABLE_PATH = path.resolve(
	path.join(__dirname, "../../bin/eslint.js"),
);

//-----------------------------------------------------------------------------
// Helpers
//-----------------------------------------------------------------------------

/**
 * Returns a Promise for when a child process exits
 * @param {ChildProcess} exitingProcess The child process
 * @returns {Promise<number>} A Promise that fulfills with the exit code when the child process exits
 */
function awaitExit(exitingProcess) {
	return new Promise(resolve => exitingProcess.once("exit", resolve));
}

/**
 * Asserts that the exit code of a given child process will equal the given value.
 * @param {ChildProcess} exitingProcess The child process
 * @param {number} expectedExitCode The expected exit code of the child process
 * @returns {Promise<void>} A Promise that fulfills if the exit code ends up matching, and rejects otherwise.
 */
function assertExitCode(exitingProcess, expectedExitCode) {
	return awaitExit(exitingProcess).then(exitCode => {
		assert.strictEqual(
			exitCode,
			expectedExitCode,
			`Expected an exit code of ${expectedExitCode} but got ${exitCode}.`,
		);
	});
}

/**
 * Returns a Promise for the stdout of a process.
 * @param {ChildProcess} runningProcess The child process
 * @returns {Promise<{stdout: string, stderr: string}>} A Promise that fulfills with all of the
 * stdout and stderr output produced by the process when it exits.
 */
function getOutput(runningProcess) {
	let stdout = "";
	let stderr = "";

	runningProcess.stdout.on("data", data => (stdout += data));
	runningProcess.stderr.on("data", data => (stderr += data));
	return awaitExit(runningProcess).then(() => ({ stdout, stderr }));
}

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

describe("bin/eslint.js", () => {
	const forkedProcesses = new Set();

	/**
	 * Forks the process to run an instance of ESLint.
	 * @param {string[]} [args] An array of arguments
	 * @param {Object} [options] An object containing options for the resulting child process
	 * @returns {ChildProcess} The resulting child process
	 */
	function runESLint(args, options) {
		const newProcess = childProcess.fork(
			EXECUTABLE_PATH,
			args,
			{ silent: true, ...options },
		);

		forkedProcesses.add(newProcess);
		return newProcess;
	}

	/**
	 * Creates a test scenario that asserts the exit code and stdout/stderr output for a given stdin input.
	 * @param {string[]} argsArray Command line arguments
	 * @param {Object} options Process options
	 * @param {string} inputText Text to pipe into stdin
	 * @param {number} expectedExitCode Expected exit code
	 * @param {string} expectedStdout Expected stdout output (optional)
	 * @param {string} expectedStderr Expected stderr output (optional)
	 * @returns {Promise<void>} A promise that resolves when assertions complete
	 */
	function runStdinTest(
		argsArray,
		options,
		inputText,
		expectedExitCode,
		expectedStdout = "",
		expectedStderr = "",
	) {
		const child = runESLint(argsArray, options);
		child.stdin.write(inputText);
		child.stdin.end();
		return assertExitCode(child, expectedExitCode).then(() =>
			getOutput(child).then(output => {
				if (expectedStdout) {
					assert.strictEqual(output.stdout.trim(), expectedStdout);
				}
				if (expectedStderr) {
					assert.include(output.stderr, expectedStderr);
				}
				assert.strictEqual(output.stderr, expectedStderr);
			}),
		);
	}

	/**
	 * Runs a test scenario for command-line arguments and verifies exit code, output, and file state.
	 * @param {string[]} argsArray Command line arguments
	 * @param {Object} options Process options
	 * @param {string} filePath Path to file to read for expected output
	 * @param {number} expectedExitCode Expected exit code
	 * @param {string} expectedStdout Expected stdout (regex or string)
	 * @param {string} expectedStderr Expected stderr (regex or string)
	 * @returns {Promise<void>} A promise that resolves after assertions
	 */
	function runFileTest(
		argsArray,
		options,
		filePath,
		expectedExitCode,
		expectedStdout,
		expectedStderr,
	) {
		const child = runESLint(argsArray, options);
		return assertExitCode(child, expectedExitCode).then(() =>
			getOutput(child).then(output => {
				if (typeof expectedStdout === "string") {
					assert.include(output.stdout, expectedStdout);
				} else {
					assert.match(output.stdout, expectedStdout);
				}
				if (typeof expectedStderr === "string") {
					assert.include(output.stderr, expectedStderr);
				} else {
					assert.match(output.stderr, expectedStderr);
				}
			}),
		);
	}

	/**
	 * Verifies that a suppressions file has expected contents after an ESLint run.
	 * @param {string} suppressionsPath Path to suppressions file
	 * @param {Object} expectedContents Expected suppressions JSON contents
	 * @returns {Promise<void>} A promise that resolves after assertions
	 */
	function verifySuppressionsFile(suppressionsPath, expectedContents) {
		assert.isTrue(fs.existsSync(suppressionsPath));
		const actualContents = JSON.parse(fs.readFileSync(suppressionsPath, "utf8"));
		assert.deepStrictEqual(actualContents, expectedContents);
		return Promise.resolve();
	}

	/**
	 * Helper to set up a temporary file for autofix testing.
	 * @param {string} fixturesPath Path to fixture directory
	 * @param {string} sourceFileName Source file name
	 * @param {string} expectedFileName Expected file name
	 * @returns {Object} Object containing paths and text contents
	 */
	function setupAutofixTest(fixturesPath, sourceFileName, expectedFileName) {
		const tempFilePath = `${fixturesPath}/temp.js`;
		const startingText = fs.readFileSync(`${fixturesPath}/${sourceFileName}`).toString();
		const expectedFixedText = fs.readFileSync(`${fixturesPath}/${expectedFileName}`).toString();
		fs.writeFileSync(tempFilePath, startingText);
		return { tempFilePath, startingText, expectedFixedText };
	}

	/**
	 * Runs a suppression-related test suite with setup and teardown logic.
	 * @param {string} suppressionPath Path to suppression file
	 * @param {string} sourcePath Path to source file to lint
	 * @param {Array} argsWithoutSuppressions Base CLI arguments without suppressions
	 * @param {Array} argsWithSuppressions Base CLI arguments with suppressions
	 * @param {Function} testFn Function receiving test helpers to run tests
	 * @returns {void}
	 */
	function runSuppressionTestSuite(
		suppressionPath,
		sourcePath,
		argsWithoutSuppressions,
		argsWithSuppressions,
		testFn,
	) {
		beforeEach(() => {
			fs.rmSync(suppressionPath, { force: true });
		});
		afterEach(() => {
			fs.rmSync(suppressionPath, { force: true });
		});
		testFn();
	}

	/**
	 * Runs a test for cron of multiple rules with suppression.
	 * @param {ChildProcess} child The child process to run
	 * @param {string} expectedStderrRegex Regex expected in stderr
	 * @param {number} expectedExitCode Expected exit code
	 * @returns {Promise<void>} A promise that resolves after assertions
	 */
	function runInteractionTest(child, expectedStderrRegex, expectedExitCode) {
		const exitCodePromise = assertExitCode(child, expectedExitCode);
		const outputPromise = getOutput(child).then(output => {
			assert.match(output.stderr, expectedStderrRegex);
		});
		return Promise.all([exitCodePromise, outputPromise]);
	}

	/**
	 * Helper for suppressing violations using stdin.
	 * @param {string} suppressionFlag One of --suppress-all, --suppress-rule, --prune-suppressions
	 * @param {string} ruleName Rule name if --suppress-rule used
	 * @param {string} inputText Text to pipe
	 * @returns {Promise<void>} A promise that resolves after assertions
	 */
	function runStdinSuppressionTest(suppressionFlag, ruleName, inputText) {
		const args = ["--stdin", "--no-config-lookup", suppressionFlag];
		if (ruleName) {
			args.push(ruleName);
		}
		const child = runESLint(args);
		child.stdin.write(inputText);
		child.stdin.end();
		return runInteractionTest(child, /cannot be used with piped-in code/u, 2);
	}

	/**
	 * Helper that sets up tests for suppression-related scenarios.
	 * @param {string[]} argsArray Command line args
	 * @param {string} suppressionPath Path to suppressions file
	 * @param {string} expectedStderrRegex Regex expected in stderr
