	/**
	 * Generates CC and MC/DC test data for use in suppression tests.
	 * @param {string} SOURCE_PATH Path to the source file
	 * @param {Object} config Config object
	 * @returns {Object} Test config and declarations
	 */
	function setupSuppressionConfig(SOURCE_PATH, config) {
		const {
			SUPPRESSIONS_PATH,
			ARGS_WITHOUT_SUPPRESSIONS,
			ARGS_WITH_SUPPRESS_ALL,
			ARGS_WITH_SUPPRESS_RULE_INDENT,
			ARGS_WITH_SUPPRESS_RULE_INDENT_SPARSE_ARRAYS,
			ARGS_WITH_PRUNE_SUPPRESSIONS,
		} = config;

		const SUPPRESSIONS_FILE_WITH_INDENT = {
			[SOURCE_PATH]: {
				indent: {
					count: 1,
				},
			},
		};

		const SUPPRESSIONS_FILE_WITH_INDENT_SPARSE_ARRAYS = {
			[SOURCE_PATH]: {
				indent: {
					count: 1,
				},
				"no-sparse-arrays": {
					count: 2,
				},
			},
		};

		const SUPPRESSIONS_FILE_ALL_ERRORS = {
			[SOURCE_PATH]: {
				indent: { count: 1 },
				"no-sparse-arrays": { count: 2 },
				"no-undef": { count: 3 },
			},
		};

		return {
			SUPPRESSIONS_FILE_WITH_INDENT,
			SUPPRESSIONS_FILE_WITH_INDENT_SPARSE_ARRAYS,
			SUPPRESSIONS_FILE_ALL_ERRORS,
		};
	}

	/**
	 * Helper to create and verify suppression scenario.
	 * @param {ChildProcess} child Child process
	 * @param {string} suppressionPath Path to suppression file
	 * @param {Object} expectedExpected Expected suppressions
	 * @param {Object} output Output object
	 * @returns {void}
	 */
	function verifySuppressionResult(child, suppressionPath, expectedExpected, output) {
		assert.isTrue(fs.existsSync(suppressionPath));
		assert.deepStrictEqual(
			JSON.parse(fs.readFileSync(suppressionPath, "utf8")),
			expectedExpected,
		);
	}

	/**
	 * Helper to run stdin suppression test.
	 * @param {string} suppressionFlag Suppression flag
	 * @param {string} [ruleName] Rule name
	 * @param {string} inputText Input text
	 * @returns {Promise<void>} A promise that resolves after test completes
	 */
	function runSuppressionWithStdin(suppressionFlag, ruleName, inputText) {
		const child = runESLint(["--stdin", "--no-config-lookup", suppressionFlag]);
		if (ruleName) {
			child.args.push(ruleName);
		}
		child.stdin.write(inputText);
		child.stdin.end();
		return getOutput(child).then(output => {
			assert.include(
				output.stderr,
				"The --suppress-all, --suppress-rule, and --prune-suppressions options cannot be used with piped-in code.",
			);
		});
	}

