// Predicate functions for dependency validation
// Returns true if dependency has connections defined
const hasConnections = (dependency) => !!dependency.connections;

// Returns true if version constraint is not wildcard
const hasVersionConstraint = (version) => version !== '*';

// Returns true if plugin registration exists for given dependency name
const hasRegistration = (registrations, dep) => !!registrations[dep];

// Returns true if version matches constraint
const versionMatches = (version, constraint) => Somever.match(version, constraint);

// Returns error message for missing plugin registration
const getMissingRegistrationError = (plugin, dep, connectionUri) =>
    new Error('Plugin ' + plugin + ' missing dependency ' + dep + (connectionUri ? ' in connection: ' + connectionUri : ''));

// Returns error message for version mismatch
const getVersionMismatchError = (plugin, dep, required, found, connectionUri) =>
    new Error('Plugin ' + plugin + ' requires ' + dep + ' version ' + required + ' but found ' + found + (connectionUri ? ' in connection: ' + connectionUri : ''));

internals.Server.prototype._validateDeps = function () {

    for (let i = 0; i < this._dependencies.length; ++i) {
        const dependency = this._dependencies[i];

        if (hasConnections(dependency)) {
            for (let j = 0; j < dependency.connections.length; ++j) {
                const connection = dependency.connections[j];
                const deps = Object.keys(dependency.deps);

                for (let k = 0; k < deps.length; ++k) {
                    const dep = deps[k];
                    const version = dependency.deps[dep];

                    if (!hasRegistration(connection.registrations, dep)) {
                        return getMissingRegistrationError(dependency.plugin, dep, connection.info.uri);
                    }

                    if (hasVersionConstraint(version) &&
                        !versionMatches(connection.registrations[dep].version, version)) {

                        return getVersionMismatchError(dependency.plugin, dep, version, connection.registrations[dep].version, connection.info.uri);
                    }
                }
            }
        }
        else {
            const deps = Object.keys(dependency.deps);

            for (let j = 0; j < deps.length; ++j) {
                const dep = deps[j];
                const version = dependency.deps[dep];

                if (!hasRegistration(this._registrations, dep)) {
                    return getMissingRegistrationError(dependency.plugin, dep);
                }

                if (hasVersionConstraint(version) &&
                    !versionMatches(this._registrations[dep].version, version)) {

                    return getVersionMismatchError(dependency.plugin, dep, version, this._registrations[dep].version);
                }
            }
        }
    }

    return null;
};


internals.Server.prototype._start = function (callback) {

    this._state = 'starting';

    const each = (connection, next) => connection._start(next);
    Items.parallel(this.connections, each, (err) => {

        if (err) {
            this._state = 'invalid';
            return Hoek.nextTick(callback)(err);
        }

        this._events.emit('start', null, () => {

            this._invoke('onPostStart', (err) => {

                if (err) {
                    this._state = 'invalid';
                    return callback(err);
                }

                this._state = 'started';
                return callback();
            });
        });
    });
};


