export type Field = ReturnType<typeof makeFieldEntry>
export type List = ReturnType<typeof makeList> extends Generator<infer T, any, any> ? T : never

export function* makeList({
  prefix = ``,
  access,
  fields,
}: {
  prefix?: string
  access: {
    query: boolean
    create: boolean
    update: boolean
    delete: boolean
  }
  fields: Field[]
}) {
  const suffix = `${prefix}${makeName(access)}`
  const nameO = `List_operation_${suffix}`

  yield {
    name: nameO,
    expect: { type: 'operation' as const, ...access },
    access: {
      operation: {
        query: access.query ? allowAll : denyAll,
        create: access.create ? allowAll : denyAll,
        update: access.update ? allowAll : denyAll,
        delete: access.delete ? allowAll : denyAll,
      },
      filter: {
        query: allowAll,
        update: allowAll,
        delete: allowAll,
      },
      item: {
        create: allowAll,
        update: allowAll,
        delete: allowAll,
      },
    },
    fields,
    graphql: {
      plural: nameO + 's',
    },
  } as const

  if (hasUnavailableOperation(access)) {
    yield* makeItemAccessList(suffix, access, fields)
  }

  if (hasUnavailableOperationButQuery(access)) {
    yield* makeFilterLists(suffix, access, fields)
  }
}

function hasUnavailableOperation(access: {
  query: boolean
  create: boolean
  update: boolean
  delete: boolean
}) {
  return [access.create, access.update, access.delete].includes(false)
}

function hasUnavailableOperationButQuery(access: {
  query: boolean
  create: boolean
  update: boolean
  delete: boolean
}) {
  return [access.query, access.update, access.delete].includes(false)
}

function* makeItemAccessList(
  suffix: string,
  access: {
    query: boolean
    create: boolean
    update: boolean
    delete: boolean
  },
  fields: Field[]
) {
  const nameI = `List_item_${suffix}`

  yield {
    name: nameI,
    expect: { type: 'item' as const, ...access },
