} from '../../../../types'

// Helper: Extracts the Option object corresponding to a Key from options
// Returns null if no match is found or key is null
function findOptionByKey(key: Key | null, options: Array<{ label: string; value: unknown }>) {
  if (key == null) return null
  return options.find(opt => opt.value === key) ?? null
}

// Helper: Handles onSelectionChange for Select field
function handleSelectionChange(
  key: Key | null,
  value: Value,
  field: { options: Array<{ label: string; value: unknown }> },
  onChange: ((value: Value) => void) | null,
  setDirty: (isDirty: boolean) => void
) {
  if (!onChange) return

  const newValue = findOptionByKey(key, field.options)

  onChange({ ...value, value: newValue })
  setDirty(true)
}

// Helper: Handles null toggle for nullable fields
function handleNullToggle(
  isChecked: boolean,
  value: Value,
  preNullValue: Value['value'],
  field: { options: Array<{ label: string; value: unknown }> },
  onChange: ((value: Value) => void) | null,
  setDirty: (isDirty: boolean) => void,
  setPreNullValue: (value: Value['value']) => void
) {
  if (!onChange) return

  if (isChecked) {
    onChange({ ...value, value: null })
    setPreNullValue(value.value)
  } else {
    onChange({
      ...value,
      value: preNullValue ?? field.options[0],
    })
  }
  setDirty(true)
}

// Helper: Simplifies the validation logic into a focused function
function validate(value: Value, isRequired: boolean) {
  if (isRequired) {
    // Allow saving null values on update page (common when user lacks read access)
    if (value.kind === 'update' && value.initial === null) return true
    return value.value !== null
  }
  return true
}

export function Field(props: FieldProps<typeof controller>) {
  const { autoFocus, field, forceValidation, onChange, value, isRequired } = props
  const [isDirty, setDirty] = useState(false)
  const [preNullValue, setPreNullValue] = useState(
    value.value || (value.kind === 'update' ? value.initial : null)
  )
  const longestLabelLength = useMemo(() => {
    return field.options.reduce((a, item) => Math.max(a, item.label.length), 0)
  }, [field.options])

  const selectedKey = value.value?.value || preNullValue?.value || null
  const isNullable = !isRequired
  const isNull = isNullable && value.value?.value == null
  const isInvalid = !validate(value, isRequired)
  const isReadOnly = onChange == null
  const errorMessage =
    isInvalid && (isDirty || forceValidation) ? `${field.label} is required.` : undefined

  const onSelectionChange = (key: Key | null) => {
    handleSelectionChange(key, value, field, onChange, setDirty)
  }

  const onNullChange = (isChecked: boolean) => {
    handleNullToggle(isChecked, value, preNullValue, field, onChange, setDirty, setPreNullValue)
  }

  const fieldElement = (() => {
    switch (field.displayMode) {
      case 'segmented-control':
        return (
          <SegmentedControl
            label={field.label}
            description={field.description}
            errorMessage={errorMessage}
            isDisabled={isNull}
            isReadOnly={isReadOnly}
            isRequired={isRequired}
            items={field.options}
            onChange={onSelectionChange}
            value={selectedKey}
            textValue={field.options.find(item => item.value === selectedKey)?.label || ''}
          >
            {item => <Item key={item.value}>{item.label}</Item>}
          </SegmentedControl>
        )
      case 'radio':
        return (
          <RadioGroup
            label={field.label}
            description={field.description}
            errorMessage={errorMessage}
            isDisabled={isNull}
            isReadOnly={isReadOnly}
            isRequired={isRequired}
            onChange={onSelectionChange}
            // maintain the previous value when set to null in aid of continuity
            // for the user. it will be cleared when the item is saved
            value={value.value?.value ?? preNullValue?.value}
          >
            {field.options.map(item => (
              <Radio key={item.value} value={item.value}>
                {item.label}
              </Radio>
            ))}
          </RadioGroup>
        )
      default:
        return (
          <Picker
            autoFocus={autoFocus}
            label={field.label}
            description={field.description}
            errorMessage={errorMessage}
            isDisabled={isNull}
            isReadOnly={isReadOnly}
            isRequired={isRequired}
            items={field.options}
            onSelectionChange={onSelectionChange}
            selectedKey={selectedKey}
            flex={{ mobile: true, desktop: 'initial' }}
            UNSAFE_style={{
              fontSize: tokenSchema.typography.text.regular.size,
              width: `clamp(${tokenSchema.size.alias.singleLineWidth}, calc(${longestLabelLength}ex + ${tokenSchema.size.icon.regular}), 100%)`,
            }}
          >
            {item => <Item key={item.value}>{item.label}</Item>}
          </Picker>
        )
    }
  })()

  return (
    <NullableFieldWrapper
      isAllowed={!isRequired}
      autoFocus={isNull && autoFocus}
      label={field.label}
      isReadOnly={isReadOnly}
      isNull={isNull}
      onChange={onNullChange}
    >
      {fieldElement}
    </NullableFieldWrapper>
  )
}

