/**
 * Determines whether the field value is considered valid given the required constraint
 */
function validate(value: Value, isRequired: boolean) {
  if (isRequired) {
    // if you got null initially on the update screen, we want to allow saving
    // since the user probably doesn't have read access control
    if (value.kind === 'update' && value.initial === null) return true
    return value.value !== null
  }
  return true
}

/**
 * Renders the appropriate UI component based on display mode
 */
function renderFieldElement({
  field,
  selectedKey,
  isNull,
  isReadOnly,
  isRequired,
  errorMessage,
  autoFocus,
  longestLabelLength,
  onChange,
}: {
  field: AdminSelectFieldMeta
  selectedKey: Key
  isNull: boolean
  isReadOnly: boolean
  isRequired: boolean
  errorMessage?: string
  autoFocus: boolean
  longestLabelLength: number
  onChange: (key: Key | null) => void
}) {
  if (field.displayMode === 'segmented-control') {
    return (
      <SegmentedControl
        label={field.label}
        description={field.description}
        errorMessage={errorMessage}
        isDisabled={isNull}
        isReadOnly={isReadOnly}
        isRequired={isRequired}
        items={field.options}
        onChange={onChange}
        value={selectedKey}
        textValue={field.options.find(item => item.value === selectedKey)?.label || ''}
