} from '../../../../types'

/**
 * Validates the password value against configured rules.
 * Returns an error message if validation fails, or undefined if valid.
 */
function validate(
  value: Value,
  validation: Validation,
  isRequired: boolean,
  fieldLabel: string
): string | undefined {
  if (value.kind === 'initial') {
    return handleInitialValueValidation(value, isRequired, fieldLabel)
  }
  if (value.kind === 'editing') {
    return handleEditingValueValidation(value, validation, fieldLabel)
  }
  return undefined
}

/**
 * Validates initial (non-editing) password values.
 */
function handleInitialValueValidation(
  value: Value,
  isRequired: boolean,
  fieldLabel: string
): string | undefined {
  if (value.isSet === null || value.isSet === true) {
    return undefined
  }
  if (isRequired) {
    return `${fieldLabel} is required`
  }
  return undefined
}

/**
 * Validates editing (in-progress) password values.
 */
function handleEditingValueValidation(
  value: Value,
  validation: Validation,
  fieldLabel: string
): string | undefined {
  if (value.confirm !== value.value) {
    return `The passwords do not match`
  }

  const val = value.value

  const lengthError = validateLength(val, validation.length, fieldLabel)
  if (lengthError) return lengthError

  const matchError = validatePattern(val, validation.match, fieldLabel)
  if (matchError) return matchError

  const commonError = validateCommonPasswords(val, validation.rejectCommon, fieldLabel)
  if (commonError) return commonError

  return undefined
}

/**
 * Validates password length against min/max constraints.
 */
function validateLength(
  value: string,
  length: { min: number; max: number | null },
  fieldLabel: string
): string | undefined {
  if (value.length < length.min) {
    if (length.min === 1) {
      return `${fieldLabel} must not be empty`
    }
    return `${fieldLabel} must be at least ${length.min} characters long`
  }
  if (length.max !== null && value.length > length.max) {
    return `${fieldLabel} must be no longer than ${length.max} characters`
  }
  return undefined
}

/**
 * Validates password against custom regex pattern.
 */
function validatePattern(
  value: string,
  match: { regex: RegExp; explanation: string } | null,
  fieldLabel: string
): string | undefined {
  if (!match) return undefined
  if (!match.regex.test(value)) {
    return match.explanation
  }
  return undefined
}

/**
 * Validates password against common password list.
 */
function validateCommonPasswords(
  value: string,
  rejectCommon: boolean,
  fieldLabel: string
): string | undefined {
  if (!rejectCommon) return undefined
  if (dumbPasswords.check(value)) {
    return `${fieldLabel} is too common and is not allowed`
  }
  return undefined
}

