function getAlignmentFromElement(element: globalThis.Element): 'center' | 'end' | undefined {
  const parent = element.parentElement
  const alignment = getAlignmentFromParentDataAttribute(parent)
  if (alignment) {
    return alignment
  }

  if (element instanceof HTMLElement) {
    return getAlignmentFromElementStyle(element)
  }

  return undefined
}

/**
 * Extracts alignment value from parent's data-align attribute.
 */
function getAlignmentFromParentDataAttribute(parent: Element | null): 'center' | 'end' | undefined {
  if (!parent) {
    return undefined
  }
  const alignment = parent.dataset.align
  return alignment === 'center' || alignment === 'end' ? alignment : undefined
}

/**
 * Extracts alignment from HTMLElement's style.textAlign property.
 */
function getAlignmentFromElementStyle(element: HTMLElement): 'center' | 'end' | undefined {
  const textAlign = element.style.textAlign
  if (textAlign === 'center') {
    return 'center'
  }
  if (textAlign === 'right' || textAlign === 'end') {
    return 'end'
  }
  return undefined
}

