import type {
  CellComponent,
  FieldController,
  FieldControllerConfig,
  FieldProps,
} from '../../../../types'

/**
 * Validates the password value against the provided validation rules.
 * Returns an error message if validation fails, or undefined if valid.
 */
function validate(
  value: Value,
  validation: Validation,
  isRequired: boolean,
  fieldLabel: string
): string | undefined {
  if (value.kind === 'initial') {
    return handleInitialValue(value, isRequired, fieldLabel)
  }
  if (value.kind === 'editing') {
    return handleEditingValue(value, validation, fieldLabel)
  }
  return undefined
}

/**
 * Handles validation logic for initial-value states.
 */
function handleInitialValue(
  value: Value,
  isRequired: boolean,
  fieldLabel: string
): string | undefined {
  if (value.isSet === null || value.isSet === true) {
    return undefined
  }
  if (isRequired) {
    return `${fieldLabel} is required`
  }
  return undefined
}

/**
 * Handles validation logic for editing-value states.
 */
function handleEditingValue(
  value: Value,
  validation: Validation,
  fieldLabel: string
): string | undefined {
  if (value.confirm !== value.value) {
    return `The passwords do not match`
  }

  const val = value.value
  const lengthError = validateLength(val, validation.length, fieldLabel)
  if (lengthError) return lengthError

  if (validation.match && !validation.match.regex.test(val)) {
    return validation.match.explanation
  }

  if (validation.rejectCommon && dumbPasswords.check(val)) {
    return `${fieldLabel} is too common and is not allowed`
  }

  return undefined
}

/**
 * Validates password length against min/max constraints.
 */
function validateLength(
  value: string,
  length: Validation['length'],
  fieldLabel: string
): string | undefined {
  if (value.length < length.min) {
    if (length.min === 1) {
      return `${fieldLabel} must not be empty`
    }
    return `${fieldLabel} must be at least ${length.min} characters long`
  }

  if (length.max !== null && value.length > length.max) {
    return `${fieldLabel} must be no longer than ${length.max} characters`
  }

  return undefined
}

function readonlyCheckboxProps(isSet: null | undefined | boolean) {
  const isIndeterminate = isSet == null
  const isSelected = isSet == null ? undefined : isSet
  return {
    children: isIndeterminate ? 'Access denied' : 'Value is set',
    isIndeterminate,
    isReadOnly: true,
    isSelected,
    prominence: 'low' as const,
  }
}

export function Field(props: FieldProps<typeof controller>) {
  const { autoFocus, field, forceValidation, onChange, value } = props

  const [secureTextEntry, setSecureTextEntry] = useState(true)
  const [touched, setTouched] = useState({ value: false, confirm: false })
  const triggerRef = useRef<HTMLButtonElement>(null)

  const isReadOnly = onChange == null
  const validationMessage =
    forceValidation || (touched.value && touched.confirm)
      ? validate(value, field.validation, props.isRequired, field.label)
      : undefined

  const labelId = useId()
  const descriptionId = useSlotId([!!field.description, !!validationMessage])
  const messageId = useSlotId([!!field.description, !!validationMessage])

  const cancelEditing = () => {
    onChange?.({ kind: 'initial', isSet: value.isSet })
    setTimeout(() => {
      triggerRef.current?.focus()
    }, 0)
  }
  const onEscape = (e: React.KeyboardEvent) => {
    if (e.key !== 'Escape' || value.kind !== 'editing') return
    if (value.value === '' && value.confirm === '') {
      cancelEditing()
    }
  }

  // reset when the user cancels, or when the form is submitted
  useEffect(() => {
    if (value.kind === 'initial') {
      setTouched({ value: false, confirm: false })
      setSecureTextEntry(true)
    }
  }, [value.kind])

  return (
    <VStack
      role="group"
      aria-labelledby={labelId}
      aria-describedby={descriptionId}
      gap="medium"
      minWidth={0}
    >
      <FieldLabel elementType="span" id={labelId}>
        {field.label}
      </FieldLabel>
      {!!field.description && (
        <Text id={descriptionId} size="regular" color="neutralSecondary">
          {field.description}
        </Text>
      )}
      {isReadOnly ? (
        <Checkbox {...readonlyCheckboxProps(value.isSet)} />
      ) : value.kind === 'initial' ? (
        <ActionButton
          ref={triggerRef}
          alignSelf="start"
          autoFocus={autoFocus}
          onPress={() => {
            onChange({
              kind: 'editing',
              confirm: '',
              value: '',
              isSet: value.isSet,
            })
          }}
        >
          {value.isSet ? `Change ` : `Set `}
          {field.label.toLocaleLowerCase()}
        </ActionButton>
      ) : (
        <Flex
          gap="regular"
          UNSAFE_className={css({
            [containerQueries.below.tablet]: {
              flexDirection: 'column',
            },
          })}
        >
          <TextField
            autoFocus
            aria-label={`new ${field.label}`}
            aria-describedby={[descriptionId, messageId].filter(Boolean).join(' ')}
            // @ts-expect-error — needs to be fixed in "@keystar/ui"
            isInvalid={!!validationMessage}
            onBlur={() => setTouched({ ...touched, value: true })}
            onChange={text => onChange({ ...value, value: text })}
            onKeyDown={onEscape}
            placeholder="New"
            type={secureTextEntry ? 'password' : 'text'}
            value={value.value}
            flex
          />
          <TextField
            aria-label={`confirm ${field.label}`}
            aria-describedby={messageId} // don't repeat the description announcement for the confirm field
            // @ts-expect-error — needs to be fixed in "@keystar/ui"
            isInvalid={!!validationMessage}
            onBlur={() => setTouched({ ...touched, confirm: true })}
            onChange={text => onChange({ ...value, confirm: text })}
            onKeyDown={onEscape}
            placeholder="Confirm"
            type={secureTextEntry ? 'password' : 'text'}
            value={value.confirm}
            flex
          />

          <Flex gap="regular">
            <ToggleButton
              aria-label="show"
              isSelected={!secureTextEntry}
              onPress={() => setSecureTextEntry(bool => !bool)}
            >
              <Icon src={eyeIcon} />
              <Text
                UNSAFE_className={css({
                  [containerQueries.above.mobile]: {
                    display: 'none',
                  },
                })}
              >
                Show
              </Text>
            </ToggleButton>
            <ActionButton onPress={cancelEditing}>Cancel</ActionButton>
          </Flex>
        </Flex>
      )}
      {!!validationMessage && <FieldMessage id={messageId}>{validationMessage}</FieldMessage>}
    </VStack>
  )
}

export const Cell: CellComponent<typeof controller> = ({ value }) => {
  return value !== null ? (
    <div aria-label="is set" style={{ display: 'flex' }}>
