        const [isDirty, setDirty] = useState(false)
        if (type === 'empty' || type === 'not_empty') return null

        const labelProps =
          context === 'add' ? { label: config.label, description: typeLabel } : { label: typeLabel }

        return (
          <NumberField
            {...otherProps}
            {...labelProps}
            autoFocus={autoFocus}
            errorMessage={
              (forceValidation || isDirty) &&
              !validate({ kind: 'update', initial: null, value }, { isRequired: true })
                ? 'Required'
                : null
            }
            step={1}
            width="auto"
            onBlur={() => setDirty(true)}
            onChange={x => onChange?.(!Number.isFinite(x) ? null : x)}
            value={value ?? NaN}
          />
        )
      },

      graphql: ({ type, value }) => {
        if (type === 'empty') return { [config.fieldKey]: { equals: null } }
        if (type === 'not_empty') return { [config.fieldKey]: { not: { equals: null } } }
        if (type === 'not') return { [config.fieldKey]: { not: { equals: value } } }
        return { [config.fieldKey]: { [type]: value } }
      },
      parseGraphQL: value => {
        return entriesTyped(value).flatMap(([type, value]) => {
          if (type === 'equals' && value === null) {
            return [{ type: 'empty', value: null }]
          }
          if (!value) return []
          if (type === 'equals') return { type: 'equals', value }
          if (type === 'not') {
            if (value?.equals === null) return { type: 'not_empty', value: null }
            if (value?.equals === undefined) return []
            return { type: 'not', value: value.equals }
          }
          if (type === 'gt' || type === 'gte' || type === 'lt' || type === 'lte') {
            return { type, value }
          }
          return []
        })
      },
      Label({ label, type, value }) {
        if (type === 'empty' || type === 'not_empty') return label.toLocaleLowerCase()
        const operator = TYPE_OPERATOR_MAP[type as keyof typeof TYPE_OPERATOR_MAP]
        return `${operator} ${value}`
      },
      types: {
        equals: {
          label: 'Is exactly',
          initialValue: null,
        },
        not: {
          label: 'Is not exactly',
          initialValue: null,
        },
        gt: {
          label: 'Is greater than',
          initialValue: null,
        },
        lt: {
          label: 'Is less than',
          initialValue: null,
        },
        gte: {
          label: 'Is greater than or equal to',
          initialValue: null,
        },
        lte: {
          label: 'Is less than or equal to',
          initialValue: null,
        },
        empty: {
          label: 'Is empty',
          initialValue: null,
        },
        not_empty: {
          label: 'Is not empty',
          initialValue: null,
        },
      },
    },
  }
}

/**
 * Renders an auto-increment field in read-only mode.
 */
function AutoIncrementField({ field, autoFocus }: { field: typeof controller extends FieldController<infer V, infer R, infer I> ? { hasAutoIncrementDefault: boolean } & Omit<ReturnType<typeof controller>, 'hasAutoIncrementDefault'> : any; autoFocus?: boolean }) {
  return (
    <NumberField
      autoFocus={autoFocus}
      description={field.description}
      label={field.label}
      isReadOnly
      contextualHelp={
        <ContextualHelp>
          <Heading>Auto increment</Heading>
          <Content>
            <Text>
              This field is set to auto increment. It will default to the next available number.
            </Text>
          </Content>
        </ContextualHelp>
      }
    />
  )
}

/**
 * Renders the editable number field.
 */
function EditableNumberField({
  field,
  value,
  onChange,
  autoFocus,
  forceValidation,
  isRequired,
  isDirty,
  setIsDirty,
}: {
  field: typeof controller extends FieldController<infer V, infer R, infer I> ? { validation: Validation; hasAutoIncrementDefault: boolean; label: string; description?: string } & Omit<ReturnType<typeof controller>, 'validation' | 'hasAutoIncrementDefault' | 'label' | 'description'> : any
  value: Value
  onChange: ((val: any) => void) | undefined
  autoFocus?: boolean
  forceValidation?: boolean
  isRequired: boolean
  isDirty: boolean
  setIsDirty: (isDirty: boolean) => void
}) {
  const validate = (value: Value): string | undefined => {
    return validate_(
      value,
      field.validation,
      isRequired,
      field.label,
      field.hasAutoIncrementDefault
    )
  }

  return (
    <NumberField
      autoFocus={autoFocus}
      description={field.description}
      label={field.label}
      errorMessage={(forceValidation || isDirty) && validate(value)}
      isReadOnly={!onChange || field.hasAutoIncrementDefault}
      isRequired={isRequired}
      width="alias.singleLineWidth"
      onBlur={() => setIsDirty(true)}
      onChange={x => onChange?.({ ...value, value: safeParseNumber(x) })}
      value={value.value ?? NaN}
    />
  )
}

export function Field({
  field,
  value,
  onChange,
  autoFocus,
  forceValidation,
  isRequired,
}: FieldProps<typeof controller>) {
  const [isDirty, setIsDirty] = useState(false)

  if (isAutoIncrementCreateMode(value, field.hasAutoIncrementDefault)) {
    return <AutoIncrementField field={field} autoFocus={autoFocus} />
  }

  return (
    <EditableNumberField
      field={field}
      value={value}
      onChange={onChange}
      autoFocus={autoFocus}
      forceValidation={forceValidation}
      isRequired={isRequired}
      isDirty={isDirty}
      setIsDirty={setIsDirty}
    />
  )
}

