         * Build configuration array for the profile.
         */
        _buildConfigArray: function() {
            return _.map(this.configs, (item, key) => {
                if (key === 'encrypt') {
                    item = '0';
                }
                if (key === 'encryptBackup') {
                    item = {};
                }
                if (key === 'appProfiles') {
                    item = JSON.stringify(item);
                }
                return {name: key, value: item};
            });
