  CLI.prototype.remote = function(command, opts, cb) {
    var that = this;

    that[command](opts.name, function(err_cmd, ret) {
      if (err_cmd) {
        console.error(err_cmd);
      }
      console.log('Command %s finished', command);
      return cb(err_cmd, ret);
    });
