    _.defaults(options, this.options);

    const modelAttributeMap = this._buildModelAttributeMap(modelAttributes);
    const { fields, values, outputFragment, tmpTable } = this._extractInsertFieldsAndValues(
      table, valueHash, modelAttributeMap, options
