    return this._composeInsertQuery(table, fields, values, outputFragment, tmpTable, options, modelAttributeMap);
  },

  _buildModelAttributeMap(modelAttributes) {
    if (!modelAttributes) return {};

    const modelAttributeMap = {};
    _.each(modelAttributes, (attribute, key) => {
      modelAttributeMap[key] = attribute;
      if (attribute.field) {
        modelAttributeMap[attribute.field] = attribute;
      }
    });
    return modelAttributeMap;
  },

  _extractInsertFieldsAndValues(table, valueHash, modelAttributeMap, options) {
    const fields = [];
    const values = [];
    let outputFragment;
    let tmpTable = '';
    const isReturnValuesSupported = this._dialect.supports.returnValues;
    const hasTrigger = options.hasTrigger && this._dialect.supports.tmpTableTrigger;

    if (isReturnValuesSupported && options.returning) {
      this._processReturnValues(options, modelAttributes, (fragment, columns) => {
        outputFragment = fragment;
        if (hasTrigger && modelAttributes) {
          tmpTable = this._buildTmpTableForTrigger(columns, modelAttributes, table);
