          list => {
            return fromJS(makeUnique([...list.toJS(), ...newComponents]));
          }
        )
        .updateIn(['modifiedData', 'components'], old => {
          return newComponents.reduce((acc, current) => {
            return addComponentsToState(state, current, acc);
