              return loader.load({ filters }).then(r => assignOptions(r, obj));
            }

            if (
              nature === 'manyWay' ||
              (nature === 'manyToMany' && association.dominant === true)
            ) {
              return buildManyToManyResolver(loader, obj, alias, targetPK, targetModel, model, localId, primaryKey);
            }
          };
          break;
        }
      }

      return resolver;
    }, {});
