/**
 * Retrieves LinkedIn profile.
 *
 * @param {String}   access_token
 * @param {Function} callback
 */
const getLinkedInProfile = (access_token, callback) => {
  const linkedIn = purest({
    provider: 'linkedin',
    config: {
      linkedin: {
        'https://api.linkedin.com': {
          __domain: {
            auth: [{ auth: { bearer: '[0]' } }],
          },
          '[version]/{endpoint}': {
            __path: {
              alias: '__default',
              version: 'v2',
            },
          },
        },
      },
    },
  });

  const getDetailsRequest = () => {
    return new Promise((resolve, reject) => {
      linkedIn
        .query()
        .get('me')
        .auth(access_token)
        .request((err, res, body) => {
          if (err) {
            return reject(err);
          }
          resolve(body);
        });
    });
  };

  const getEmailRequest = () => {
    return new Promise((resolve, reject) => {
      linkedIn
        .query()
        .get('emailAddress?q=members&projection=(elements*(handle~))')
        .auth(access_token)
        .request((err, res, body) => {
          if (err) {
            return reject(err);
          }
          resolve(body);
        });
    });
  };

  Promise.all([getDetailsRequest(), getEmailRequest()])
    .then(([details, emailResponse]) => {
      const { localizedFirstName } = details;
      const { elements } = emailResponse;
      const email = elements[0]['handle~'];

      callback(null, {
        username: localizedFirstName,
        email: email.emailAddress,
      });
    })
    .catch(err => callback(err));
};

