 */
function getLinkedInDetails(linkedIn, accessToken) {
  return new Promise((resolve, reject) => {
    linkedIn
      .query()
      .get('me')
      .auth(accessToken)
      .request((err, res, body) => {
        if (err) {
          return reject(err);
        }
        resolve(body);
