 * @returns {Object} Mapped controller actions.
 */
const generateControllerActions = controller => {
  return Object.keys(controller).reduce((acc, key) => {
    if (_.isFunction(controller[key])) {
      acc[key] = { enabled: false, policy: '' };
    }
    return acc;
