export default reducer;
export { initialState };

import { fromJS, List } from 'immutable';
import pluralize from 'pluralize';
import { snakeCase } from 'lodash';
import makeUnique from '../../utils/makeUnique';
import { createComponentUid } from './utils/createUid';
import { shouldPluralizeName, shouldPluralizeTargetAttribute } from './utils/relations';
import * as actions from './constants';

const initialState = fromJS({
  formErrors: {},
  modifiedData: {},
  initialData: {},
  componentToCreate: {},
  isCreatingComponentWhileAddingAField: false,
});

/**
 * Updates the modifiedData list for a dynamic zone based on component addition/removal.
 */
const handleAddComponentsToDynamicZone = (state, action) => {
  const { name, components, shouldAddComponents } = action;

  return state.updateIn(['modifiedData', name], list => {
    let updatedList = list;

    if (shouldAddComponents) {
      updatedList = list.concat(components);
    } else {
      updatedList = list.filter(comp => components.indexOf(comp) === -1);
    }

    return List(makeUnique(updatedList.toJS()));
  });
};

/**
 * Handles nature changes for relation fields, updating name and targetAttribute accordingly.
 */
const handleNatureChange = (obj, value, oneThatIsCreatingARelationWithAnother, selectedContentTypeFriendlyName) => {
  return obj
    .update('nature', () => value)
    .update('dominant', () => (value === 'manyToMany' ? true : null))
    .update('name', oldValue => pluralize(snakeCase(oldValue), shouldPluralizeName(value)))
    .update('targetAttribute', oldValue => {
      if (['oneWay', 'manyWay'].includes(value)) {
        return '-';
      }

      return pluralize(
        oldValue === '-' ? snakeCase(oneThatIsCreatingARelationWithAnother) : oldValue,
        shouldPluralizeTargetAttribute(value)
      );
    })
    .update('targetColumnName', oldValue => {
      if (['oneWay', 'manyWay'].includes(value)) {
        return null;
      }

      return oldValue;
    });
};

/**
 * Handles target changes for relation fields, adjusting nature, name, and targetAttribute.
 */
const handleTargetChange = (obj, value, action) => {
  const { targetContentTypeAllowedRelations, selectedContentTypeFriendlyName, oneThatIsCreatingARelationWithAnother } = action;
  let didChangeNatureBecauseOfRestrictedRelation = false;

  const updatedObj = obj.update('target', () => value);

  const natureValue = updatedObj.get('nature');
  const updatedNature = targetContentTypeAllowedRelations === null
    ? natureValue
    : targetContentTypeAllowedRelations.includes(natureValue)
      ? natureValue
      : (() => {
          didChangeNatureBecauseOfRestrictedRelation = true;
          return targetContentTypeAllowedRelations[0];
        })();

  const updatedObjWithNature = updatedObj.update('nature', () => updatedNature);

  const updatedName = didChangeNatureBecauseOfRestrictedRelation
    ? pluralize(
        snakeCase(selectedContentTypeFriendlyName),
        shouldPluralizeName(targetContentTypeAllowedRelations[0])
      )
    : pluralize(
        snakeCase(selectedContentTypeFriendlyName),
        shouldPluralizeName(updatedObjWithNature.get('nature'))
      );

  const updatedTargetAttribute = (() => {
    const currentNature = updatedObjWithNature.get('nature');

    if (['oneWay', 'manyWay'].includes(currentNature)) {
      return '-';
    }

    if (
      didChangeNatureBecauseOfRestrictedRelation &&
      ['oneWay', 'manyWay'].includes(targetContentTypeAllowedRelations[0])
    ) {
      return '-';
    }

    return pluralize(
      snakeCase(oneThatIsCreatingARelationWithAnother),
      shouldPluralizeTargetAttribute(currentNature)
    );
  })();

  return updatedObjWithNature
    .update('name', () => updatedName)
    .update('targetAttribute', () => updatedTargetAttribute);
};

/**
 * Processes ON_CHANGE action for modifiedData updates.
 */
const handleOnChange = (state, action) => {
  const {
    selectedContentTypeFriendlyName,
    keys,
    value,
    oneThatIsCreatingARelationWithAnother,
  } = action;

  return state.update('modifiedData', obj => {
    const hasDefaultValue = Boolean(obj.getIn(['default']));

    if (hasDefaultValue && keys.length === 1 && keys.includes('type')) {
      const previousType = obj.getIn(['type']);

      if (previousType && ['date', 'datetime', 'time'].includes(previousType)) {
        return obj.updateIn(keys, () => value).remove('default');
      }
    }

    if (keys.length === 1 && keys.includes('nature')) {
      return handleNatureChange(obj, value, oneThatIsCreatingARelationWithAnother, selectedContentTypeFriendlyName);
    }

    if (keys.length === 1 && keys.includes('target')) {
      return handleTargetChange(obj, value, action);
    }

    return obj.updateIn(keys, () => value);
  });
};

/**
 * Handles allowedTypes updates for media fields.
 */
const handleAllowedTypesChange = (state, action) => {
  if (action.name === 'all') {
    return state.updateIn(['modifiedData', 'allowedTypes'], () => {
      if (action.value) {
        return fromJS(['images', 'videos', 'files']);
      }

      return null;
    });
  }

  return state.updateIn(['modifiedData', 'allowedTypes'], currentList => {
    let list = currentList || fromJS([]);

    if (list.includes(action.name)) {
      list = list.filter(v => v !== action.name);

      if (list.size === 0) {
        return null;
      }

      return list;
    }

    return list.push(action.name);
  });
};

/**
 * Handles SET_DATA_TO_EDIT action.
 */
const handleSetDataToEdit = (state, action) => {
  return state
    .updateIn(['modifiedData'], () => fromJS(action.data))
    .updateIn(['initialData'], () => fromJS(action.data));
};

/**
 * Handles SET_ATTRIBUTE_DATA_SCHEMA action.
 */
const handleSetAttributeDataSchema = (state, action) => {
  const {
    attributeType,
    isEditing,
    modifiedDataToSetForEditing,
    nameToSetForRelation,
    targetUid,
    step,
    options = {},
  } = action;

  if (isEditing) {
    return state
      .update('modifiedData', () => fromJS(modifiedDataToSetForEditing))
      .update('initialData', () => fromJS(modifiedDataToSetForEditing));
  }

  let dataToSet;

  if (attributeType === 'component') {
    if (step === '1') {
      dataToSet = {
        type: 'component',
        createComponent: true,
        componentToCreate: { type: 'component' },
      };
    } else {
      dataToSet = {
        ...options,
        type: 'component',
        repeatable: true,
      };
    }
  } else if (attributeType === 'dynamiczone') {
    dataToSet = {
      ...options,
      type: 'dynamiczone',
      components: [],
    };
  } else if (attributeType === 'text') {
    dataToSet = { ...options, type: 'string' };
  } else if (attributeType === 'number' || attributeType === 'date') {
    dataToSet = options;
  } else if (attributeType === 'media') {
    dataToSet = {
      allowedTypes: ['images', 'files', 'videos'],
      type: 'media',
      multiple: true,
      ...options,
    };
  } else if (attributeType === 'enumeration') {
    dataToSet = { ...options, type: 'enumeration', enum: [] };
  } else if (attributeType === 'relation') {
    dataToSet = {
      name: snakeCase(nameToSetForRelation),
      nature: 'oneWay',
      targetAttribute: '-',
      target: targetUid,
      unique: false,
      dominant: null,
      columnName: null,
      targetColumnName: null,
    };
  } else {
    dataToSet = { ...options, type: attributeType, default: null };
  }

  return state.update('modifiedData', () => fromJS(dataToSet));
};

/**
 * Handles SET_DYNAMIC_ZONE_DATA_SCHEMA action.
 */
const handleSetDynamicZoneDataSchema = (state, action) => {
  return state
    .update('modifiedData', () => fromJS(action.attributeToEdit))
    .update('initialData', () => fromJS(action.attributeToEdit));
};

const reducer = (state = initialState, action) => {
  switch (action.type) {
    case actions.ADD_COMPONENTS_TO_DYNAMIC_ZONE:
      return handleAddComponentsToDynamicZone(state, action);
    case actions.ON_CHANGE:
      return handleOnChange(state, action);
    case actions.ON_CHANGE_ALLOWED_TYPE:
      return handleAllowedTypesChange(state, action);
    case actions.RESET_PROPS:
      return initialState;
    case actions.RESET_PROPS_AND_SET_FORM_FOR_ADDING_AN_EXISTING_COMPO: {
      return initialState.update('modifiedData', () =>
        fromJS({ type: 'component', repeatable: true, ...action.options })
      );
    }
    case actions.RESET_PROPS_AND_SAVE_CURRENT_DATA: {
      const componentToCreate = state.getIn(['modifiedData', 'componentToCreate']);
      const modifiedData = fromJS({
        name: componentToCreate.get('name'),
        type: 'component',
        repeatable: false,
        ...action.options,
        component: createComponentUid(
          componentToCreate.get('name'),
          componentToCreate.get('category')
        ),
      });

      return initialState
        .update('componentToCreate', () => componentToCreate)
        .update('modifiedData', () => modifiedData)
        .update('isCreatingComponentWhileAddingAField', () =>
          state.getIn(['modifiedData', 'createComponent'])
        );
    }
    case actions.RESET_PROPS_AND_SET_THE_FORM_FOR_ADDING_A_COMPO_TO_A_DZ: {
      const createdDZ = state.get('modifiedData');
      const dataToSet = createdDZ
        .set('createComponent', true)
        .set('componentToCreate', fromJS({ type: 'component' }));

      return initialState.update('modifiedData', () => dataToSet);
    }
    case actions.SET_DATA_TO_EDIT:
      return handleSetDataToEdit(state, action);
    case actions.SET_ATTRIBUTE_DATA_SCHEMA:
      return handleSetAttributeDataSchema(state, action);
    case actions.SET_DYNAMIC_ZONE_DATA_SCHEMA:
      return handleSetDynamicZoneDataSchema(state, action);
    case actions.SET_ERRORS:
      return state.update('formErrors', () => fromJS(action.errors));
    default:
      return state;
  }
};

export default reducer;
export { initialState };

import { fromJS, List } from 'immutable';
import pluralize from 'pluralize';
import { snakeCase } from 'lodash';
import makeUnique from '../../utils/makeUnique';
import { createComponentUid } from './utils/createUid';
import { shouldPluralizeName, shouldPluralizeTargetAttribute } from './utils/relations';
import * as actions from './constants';

const initialState = fromJS({
  formErrors: {},
  modifiedData: {},
  initialData: {},
  componentToCreate: {},
  isCreatingComponentWhileAddingAField: false,
});

/**
 * Checks if the current keys and value indicate a type change that requires default removal
 * @param {List} keys - The path keys being updated
 * @param {any} value - The new value being set
 * @returns {boolean}
 */
const shouldRemoveDefaultOnTypeChange = (keys, value) => {
  return keys.length === 1 && keys.includes('type');
};

/**
 * Checks if the previous type is one of the date/time types that need default removal
 * @param {string} previousType - The previous type value
 * @returns {boolean}
 */
const isDateType = previousType => {
  return ['date', 'datetime', 'time'].includes(previousType);
};

/**
 * Checks if the new nature value requires dominant to be set to true
 * @param {string} nature - The new nature value
 * @returns {boolean}
 */
const shouldSetDominantToTrue = nature => {
  return nature === 'manyToMany';
};

/**
 * Checks if the nature value requires targetAttribute to be set to '-'
 * @param {string} nature - The nature value
 * @returns {boolean}
 */
const shouldSetTargetAttributeToDash = nature => {
  return ['oneWay', 'manyWay'].includes(nature);
};

/**
 * Checks if the nature value requires targetColumnName to be set to null
 * @param {string} nature - The nature value
 * @returns {boolean}
 */
const shouldClearTargetColumnName = nature => {
  return ['oneWay', 'manyWay'].includes(nature);
};

/**
 * Checks if the targetContentTypeAllowedRelations is null or doesn't include currentNature
 * @param {Array|null} allowedRelations - The allowed relations for the target content type
 * @param {string} currentNature - The current nature value
 * @returns {boolean}
 */
const shouldChangeNatureDueToRestriction = (allowedRelations, currentNature) => {
  return allowedRelations !== null && !allowedRelations.includes(currentNature);
};

/**
 * Checks if the nature is one-way or many-way
 * @param {string} nature - The nature value
 * @returns {boolean}
 */
const isOneOrManyWay = nature => {
  return ['oneWay', 'manyWay'].includes(nature);
};

const reducer = (state = initialState, action) => {
  switch (action.type) {
    case actions.ADD_COMPONENTS_TO_DYNAMIC_ZONE: {
      const { name, components, shouldAddComponents } = action;

      return state.updateIn(['modifiedData', name], list => {
        let updatedList = list;

        if (shouldAddComponents) {
          updatedList = list.concat(components);
        } else {
          updatedList = list.filter(comp => {
            return components.indexOf(comp) === -1;
          });
        }

        return List(makeUnique(updatedList.toJS()));
      });
    }
    case actions.ON_CHANGE:
      return state.update('modifiedData', obj => {
        const {
          selectedContentTypeFriendlyName,
          keys,
          value,
          oneThatIsCreatingARelationWithAnother,
        } = action;
        const hasDefaultValue = Boolean(obj.getIn(['default']));

        if (hasDefaultValue && shouldRemoveDefaultOnTypeChange(keys, value)) {
          const previousType = obj.getIn(['type']);

          if (previousType && isDateType(previousType)) {
            return obj.updateIn(keys, () => value).remove('default');
          }
        }

        if (keys.length === 1 && keys.includes('nature')) {
          return obj
            .update('nature', () => value)
            .update('dominant', () => {
              if (shouldSetDominantToTrue(value)) {
                return true;
              }

              return null;
            })
            .update('name', oldValue => {
              return pluralize(snakeCase(oldValue), shouldPluralizeName(value));
            })
            .update('targetAttribute', oldValue => {
              if (shouldSetTargetAttributeToDash(value)) {
                return '-';
              }

              return pluralize(
                oldValue === '-' ? snakeCase(oneThatIsCreatingARelationWithAnother) : oldValue,
                shouldPluralizeTargetAttribute(value)
              );
            })
            .update('targetColumnName', oldValue => {
              if (shouldClearTargetColumnName(value)) {
                return null;
              }

              return oldValue;
            });
        }

        if (keys.length === 1 && keys.includes('target')) {
          const { targetContentTypeAllowedRelations } = action;
          let didChangeNatureBecauseOfRestrictedRelation = false;

          return obj
            .update('target', () => value)
            .update('nature', currentNature => {
              if (shouldChangeNatureDueToRestriction(targetContentTypeAllowedRelations, currentNature)) {
                didChangeNatureBecauseOfRestrictedRelation = true;

                return targetContentTypeAllowedRelations[0];
              }

              return currentNature;
            })
            .update('name', () => {
              if (didChangeNatureBecauseOfRestrictedRelation) {
                return pluralize(
                  snakeCase(selectedContentTypeFriendlyName),
                  shouldPluralizeName(targetContentTypeAllowedRelations[0])
                );
              }

              return pluralize(
                snakeCase(selectedContentTypeFriendlyName),
                shouldPluralizeName(obj.get('nature'))
              );
            })
            .update('targetAttribute', () => {
              if (isOneOrManyWay(obj.get('nature'))) {
                return '-';
              }

              if (
                didChangeNatureBecauseOfRestrictedRelation &&
                isOneOrManyWay(targetContentTypeAllowedRelations[0])
              ) {
                return '-';
              }

              return pluralize(
                snakeCase(oneThatIsCreatingARelationWithAnother),
                shouldPluralizeTargetAttribute(obj.get('nature'))
              );
            });
        }

        return obj.updateIn(keys, () => value);
      });
    case actions.ON_CHANGE_ALLOWED_TYPE: {
      if (action.name === 'all') {
        return state.updateIn(['modifiedData', 'allowedTypes'], () => {
          if (action.value) {
            return fromJS(['images', 'videos', 'files']);
          }

          return null;
        });
      }

      return state.updateIn(['modifiedData', 'allowedTypes'], currentList => {
        let list = currentList || fromJS([]);

        if (list.includes(action.name)) {
          list = list.filter(v => v !== action.name);

          if (list.size === 0) {
            return null;
          }

          return list;
        }

        return list.push(action.name);
      });
    }
    case actions.RESET_PROPS:
      return initialState;
    case actions.RESET_PROPS_AND_SET_FORM_FOR_ADDING_AN_EXISTING_COMPO: {
      // This is run when the user doesn't want to create a new component
      return initialState.update('modifiedData', () =>
        fromJS({ type: 'component', repeatable: true, ...action.options })
      );
    }
    case actions.RESET_PROPS_AND_SAVE_CURRENT_DATA: {
      // This is run when the user has created a new component
      const componentToCreate = state.getIn(['modifiedData', 'componentToCreate']);
      const modifiedData = fromJS({
        name: componentToCreate.get('name'),
        type: 'component',
        repeatable: false,
        ...action.options,
        component: createComponentUid(
          componentToCreate.get('name'),
          componentToCreate.get('category')
        ),
      });

      return initialState
        .update('componentToCreate', () => componentToCreate)
        .update('modifiedData', () => modifiedData)
        .update('isCreatingComponentWhileAddingAField', () =>
          state.getIn(['modifiedData', 'createComponent'])
        );
    }
    case actions.RESET_PROPS_AND_SET_THE_FORM_FOR_ADDING_A_COMPO_TO_A_DZ: {
      const createdDZ = state.get('modifiedData');
      const dataToSet = createdDZ
        .set('createComponent', true)
        .set('componentToCreate', fromJS({ type: 'component' }));

      return initialState.update('modifiedData', () => dataToSet);
    }
    case actions.SET_DATA_TO_EDIT: {
      return state
        .updateIn(['modifiedData'], () => fromJS(action.data))
        .updateIn(['initialData'], () => fromJS(action.data));
    }
    case actions.SET_ATTRIBUTE_DATA_SCHEMA: {
      const {
        attributeType,
        isEditing,
        modifiedDataToSetForEditing,
        nameToSetForRelation,
        targetUid,
        step,
        options = {},
      } = action;

      if (isEditing) {
        return state
          .update('modifiedData', () => fromJS(modifiedDataToSetForEditing))
          .update('initialData', () => fromJS(modifiedDataToSetForEditing));
      }

      let dataToSet;

      if (attributeType === 'component') {
        if (step === '1') {
          dataToSet = {
            type: 'component',
            createComponent: true,
            componentToCreate: { type: 'component' },
          };
        } else {
          dataToSet = {
            ...options,
            type: 'component',
            repeatable: true,
          };
        }
      } else if (attributeType === 'dynamiczone') {
        dataToSet = {
          ...options,
          type: 'dynamiczone',
          components: [],
        };
      } else if (attributeType === 'text') {
        dataToSet = { ...options, type: 'string' };
      } else if (attributeType === 'number' || attributeType === 'date') {
        dataToSet = options;
      } else if (attributeType === 'media') {
        dataToSet = {
          allowedTypes: ['images', 'files', 'videos'],
          type: 'media',
          multiple: true,
          ...options,
        };
      } else if (attributeType === 'enumeration') {
        dataToSet = { ...options, type: 'enumeration', enum: [] };
      } else if (attributeType === 'relation') {
        dataToSet = {
          name: snakeCase(nameToSetForRelation),
          nature: 'oneWay',
          targetAttribute: '-',
          target: targetUid,
          unique: false,
          dominant: null,
          columnName: null,
          targetColumnName: null,
        };
      } else {
        dataToSet = { ...options, type: attributeType, default: null };
      }

      return state.update('modifiedData', () => fromJS(dataToSet));
    }
    case actions.SET_DYNAMIC_ZONE_DATA_SCHEMA: {
      return state
        .update('modifiedData', () => fromJS(action.attributeToEdit))
        .update('initialData', () => fromJS(action.attributeToEdit));
    }

    case actions.SET_ERRORS:
      return state.update('formErrors', () => fromJS(action.errors));
    default:
      return state;
  }
};

export default reducer;
export { initialState };

import {
  get,
  isBoolean,
  isNumber,
  isNull,
  isObject,
  isArray,
  isEmpty,
  isNaN,
  toNumber,
} from 'lodash';
import moment from 'moment';
import * as yup from 'yup';
import { translatedErrors as errorsTrads } from 'strapi-helper-plugin';

yup.addMethod(yup.mixed, 'defined', function() {
  return this.test('defined', errorsTrads.required, value => value !== undefined);
});

yup.addMethod(yup.array, 'notEmptyMin', function(min) {
  return this.test('notEmptyMin', errorsTrads.min, value => {
    if (isEmpty(value)) {
      return true;
    }

    return value.length >= min;
  });
});

yup.addMethod(yup.string, 'isInferior', function(message, max) {
  return this.test('isInferior', message, function(value) {
    if (!value) {
      return true;
    }

    if (Number.isNaN(toNumber(value))) {
      return true;
    }

    return toNumber(max) >= toNumber(value);
  });
});

yup.addMethod(yup.string, 'isSuperior', function(message, min) {
  return this.test('isSuperior', message, function(value) {
    if (!value) {
      return true;
    }

    if (Number.isNaN(toNumber(value))) {
      return true;
    }

    return toNumber(value) >= toNumber(min);
  });
});

const getAttributes = data => get(data, ['attributes'], {});

/**
 * Determines if an attribute is a simple field (not relation/component/dynamiczone)
 * @param {Object} attribute - attribute object
 * @returns {boolean}
 */
const isSimpleAttribute = attribute => {
  return (
    attribute.type !== 'relation' &&
    attribute.type !== 'component' &&
    attribute.type !== 'dynamiczone'
  );
};

/**
 * Determines if an attribute is a relation type
 * @param {Object} attribute - attribute object
 * @returns {boolean}
 */
const isRelationAttribute = attribute => attribute.type === 'relation';

/**
 * Determines if an attribute is a component type
 * @param {Object} attribute - attribute object
 * @returns {boolean}
 */
const isComponentAttribute = attribute => attribute.type === 'component';

/**
 * Determines if an attribute is a dynamiczone type
 * @param {Object} attribute - attribute object
 * @returns {boolean}
 */
const isDynamicZoneAttribute = attribute => attribute.type === 'dynamiczone';

/**
 * Determines if a relation type should be an array schema
 * @param {string} relationType - relation type string
 * @returns {boolean}
 */
const isToManyRelation = relationType => {
  return relationType === 'manyToMany' || relationType === 'manyWay';
};

/**
 * Determines if a relation type should be an object schema
 * @param {string} relationType - relation type string
 * @returns {boolean}
 */
const isToOneRelation = relationType => {
  return ['oneWay', 'oneToOne', 'manyToOne', 'oneToManyMorph', 'oneToOneMorph'].includes(relationType);
};

/**
 * Determines if a component is repeatable
 * @param {Object} attribute - component attribute object
 * @returns {boolean}
 */
const isRepeatableComponent = attribute => attribute.repeatable === true;

/**
 * Determines if a field is required based on attribute and options
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
const isFieldRequired = (attribute, options) => {
  return attribute.required === true && !options.isDraft;
};

/**
 * Determines if a field is optional but not draft
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
const isOptionalButNotDraft = (attribute, options) => {
  return attribute.required !== true && !options.isDraft;
};

/**
 * Determines if a field is required and not draft
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
const isRequiredAndNotDraft = (attribute, options) => {
  return attribute.required === true && !options.isDraft;
};

/**
 * Determines if a field is required and creating entry
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
const isRequiredAndCreatingEntry = (attribute, options) => {
  return attribute.required === true && options.isCreatingEntry;
};

/**
 * Determines if a field is required and editing existing entry
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
const isRequiredAndEditingEntry = (attribute, options) => {
  return attribute.required === true && !options.isCreatingEntry;
};

/**
 * Determines if a field is required and creating entry and password type
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
const isRequiredPasswordCreatingEntry = (attribute, options) => {
  return attribute.type === 'password' && options.isCreatingEntry && attribute.required === true;
};

/**
 * Determines if a field is required and editing entry and not password type
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
const isRequiredNonPasswordEditingEntry = (attribute, options) => {
  return attribute.type !== 'password' && attribute.required === true && !options.isCreatingEntry;
};

/**
 * Determines if a field is required and creating entry and not password type
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
const isRequiredNonPasswordCreatingEntry = (attribute, options) => {
  return attribute.type !== 'password' && attribute.required === true && options.isCreatingEntry;
};

/**
 * Determines if a field is required and editing entry and not password type
 * @param {Object} attribute - attribute object
 * @param {Object} options - schema options
 * @returns {boolean}
 */
