/**
 * Extracts the maximum order value for a given morph relation from the database.
 * @param {Object} model - The model instance.
 * @param {Object} params - Relation parameters including alias, field, refId, and targetModel.
 * @param {Object} transacting - The Knex transaction instance.
 * @returns {Promise<number>} The maximum order value (default 0).
 */
const getMaxOrderForMorphRelation = async (model, { alias, field, refId, targetModel }, transacting) => {
  const maxOrderRecord = await model.morph
    .query(qb => {
      qb.max('order as order').where({
        [`${alias}_id`]: refId,
        [`${alias}_type`]: targetModel.collectionName,
        field: field,
      });
    })
    .fetch({ transacting });

  const { order = 0 } = maxOrderRecord ? maxOrderRecord.toJSON() : {};
  return order;
};

/**
 * Adds a new morph relation with computed order value.
 * @param {Object} model - The model instance.
 * @param {Object} params - Relation parameters including id, alias, ref, refId, field, and order.
 * @param {Object} transacting - The Knex transaction instance.
 * @returns {Promise<void>}
 */
const addMorphRelationWithComputedOrder = async (model, { id, alias, ref, refId, field, order }, transacting) => {
  await addRelationMorph(model, {
    params: {
      id,
      alias,
      ref,
      refId,
      field,
      order,
    },
    transacting,
  });
};

/**
 * Handles morph relation updates for manyMorphToOne and manyMorphToMany associations.
 * @param {Object} model - The model instance.
 * @param {Object} response - The current record data.
 * @param {Array} refs - Array of relation references to process.
 * @param {Object} association - The association metadata.
 * @param {Object} transacting - The Knex transaction instance.
 * @returns {Array<Promise>} Array of promises representing relation update operations.
 */
const processMorphRelationUpdates = async (model, response, refs, association, transacting) => {
  const relationUpdates = [];

  if (Array.isArray(refs) && refs.length === 0) {
    relationUpdates.push(
      removeRelationMorph(model, { params: { id: response[model.primaryKey] }, transacting })
    );
    return relationUpdates;
  }

  for (const obj of refs) {
    const targetModel = strapi.db.getModel(
      obj.ref,
      obj.source !== 'content-manager' ? obj.source : null
    );

    const reverseAssoc = targetModel.associations.find(assoc => assoc.alias === obj.field);

    if (reverseAssoc && reverseAssoc.nature === 'oneToManyMorph') {
      const removePromise = removeRelationMorph(model, {
        params: {
          alias: association.alias,
          ref: targetModel.collectionName,
          refId: obj.refId,
          field: obj.field,
        },
        transacting,
      });

      const addPromise = removePromise.then(() =>
        addRelationMorph(model, {
          params: {
            id: response[model.primaryKey],
            alias: association.alias,
            ref: targetModel.collectionName,
            refId: obj.refId,
            field: obj.field,
            order: 1,
          },
          transacting,
        })
      );

      relationUpdates.push(addPromise);
      continue;
    }

    const addRelation = async () => {
      const maxOrder = await getMaxOrderForMorphRelation(model, {
        alias: association.alias,
        field: obj.field,
        refId: obj.refId,
        targetModel,
      }, transacting);

      await addMorphRelationWithComputedOrder(model, {
        id: response[model.primaryKey],
        alias: association.alias,
        ref: targetModel.collectionName,
        refId: obj.refId,
        field: obj.field,
        order: maxOrder + 1,
      }, transacting);
    };

    relationUpdates.push(addRelation());
  }

  return relationUpdates;
};

